// Generated by scripts/build-behavior-changes.ts from behavior-changes.d/ and the CHANGELOG markers; do not edit.
// Regenerate: bun scripts/build-behavior-changes.ts (the release does it). Docs: behavior-changes.d/README.md

/** The plain-text rows of behavior-changes.d/, each dated by the release whose CHANGELOG section marks it. */
export const RELEASED_BEHAVIOR_CHANGES: ReadonlyArray<{ since: string; id: string; kind?: string; text: string }> = [
  { since: '0.60.706.0', id: 'db_wins_unimported_gst2579', text: "A database-wins file-drift repair no longer overwrites a newer change to the file that sync has not imported. `gbrain repair file-drift --prefer database` by `--held` or `--all-drifted` now lists such a page `kept_newer_file` (a file edited since the last import) or `kept_newer_delete` (a file another writer deleted) and leaves it held; naming the page with `--slug` previews it and names the commit it would discard (sha, author, date). Every file-drift apply now asks for the user's consent, so a script that applies without `--yes` exits 3. `gbrain sources reconcile --apply` refuses `source_changed` when its result takes the database copy over such an edit. A database copy newer than the file (the file still holds what sync imported, or gbrain's own write of a revision the page has since moved past) repairs as before; gbrain's own writer commit of a revision the database never took counts as newer. The keep_db policy is unchanged." },
  { since: '0.60.708.0', id: 'extract_receipt_sealed_7620', text: "An extraction run's receipt page (type `extract_receipt`, under `extracts/`) is now chunked and sealed in the transaction that writes it. Remote/MCP `search` and `query` on the extracted source no longer report `safe_index_pending` or `projection_pending` after every extraction, doctor `safe_index_pending` no longer counts new receipts, and remote readers can now find receipts like other generated pages (demoted in ranking). Receipts an earlier release wrote stay unsealed until `gbrain repair safe-chunks --apply`. A receipt is database-only bookkeeping on every brain, with or without a Git repository: when its slug already holds a content page or a page with a file in Git, the receipt is not written (the extraction logs a warning and carries on) instead of overwriting that page." },
  { since: '0.60.708.0', id: 'commit_push_dry_run_checks_paths', text: "`gbrain git commit-push --dry-run` now asks git about the planned paths the way the real run stages them, and runs the real run's checks before staging, so it exits 1 with the real run's code and text where that run would refuse (`commit_outside_source_root` for a path outside `gbrain.sourceRoot` unless `--allow-outside-source-root` is passed, `commit_prestaged_paths`, and `commit_paths_invalid` for a path outside a sparse-checkout definition or one that matches nothing) instead of exiting 0 and listing it. It still takes no lock and writes nothing." },
  { since: '0.60.708.0', id: 'schema_client_behind_7776', text: "A gbrain binary older than the brain's schema (the database's schema version is above its newest migration because a newer gbrain on another host or install migrated it) now refuses schema setup with `client_behind` and changes nothing: `gbrain init` and `init --migrate-only`, the schema step of `gbrain upgrade`, and `gbrain apply-migrations` (before any orchestrator runs, and before the schema pass of `--force-schema` or `--force-all`; `--list` and `--dry-run` still work). Before, it replayed its own older schema, which reinstalled superseded function bodies (the writer-fence guards among them) over the newer ones, and reported success. Reads and ordinary commands on the older binary are unchanged; the fix is `gbrain upgrade` on that host. A new doctor check, `schema_function_bodies`, fails when a function of this gbrain's schema has another body installed (what an older replay leaves behind) and names each one: upgrade every gbrain that shares the database, then run `gbrain init --migrate-only`. PGLite and Postgres alike, with or without a git repo." },
  { since: '0.60.708.0', id: 'purge_keeps_outcome_markers_7831', text: "Purging a fact whose text is exactly `EXTRACTION_COMPLETE` or `EXTRACTION_NOT_APPLICABLE` (`gbrain forget <id> --purge`) no longer removes the conversation-facts outcome rows that carry the same text: the purge, its receipt, `--status` and a restore replay leave them in place, so those pages are not extracted again. The purged claim itself is still removed and tombstoned." },
  { since: '0.60.708.0', id: 'audit_secrets_glued_marker_8034', text: "`gbrain transcripts audit-secrets` and re-scans of stored pages again report a password glued to an importer redaction marker by punctuation (`<REDACTED:user-pattern>,<password>`, `<REDACTED:x>.<password>`): punctuation after a marker ends it only when a space or the line end follows. Pages that hold such a line show up as affected again; import-time redaction is unchanged." },
  { since: '0.60.708.0', id: 'fence_locators_skip_code_8020', text: "A fence marker written inside markdown code (an inline `code` span or a fenced code block) no longer counts as a fence for concept republication, the Google connector's fence carry, `gbrain repair connector-fences` or `gbrain repair take-supersession`, matching how the fence readers already read the page. Pages that quote a marker in code are no longer held `concept_preservation_hold` or `connector_fence_below_timeline`, or skipped as unparsed, for that reason alone." },
  { since: '0.60.708.0', id: 'ghost_code_page_recorded_file_7967', text: "`gbrain repair ghost-pages` on a managed brain now retires a code or image page (a JSON, YAML or image file indexed as a page) at its recorded file instead of at `<slug>.md` (#7967): when that file is restored after the request was prepared, publication refuses and the page is kept (outcome `file_restored`), and the door commits the removal of the recorded file, so on a git-canonical source HEAD stops holding the file of a page the database deleted." },
  { since: '0.60.708.0', id: 'derived_write_through_retry_8092', text: "The dream cycle's atom and concept write-through (#8092) waits for a busy checkout commit lock without freezing the worker (up to 30 s, as before). After a refused commit, a rewrite of an existing atom or concept file and the removal of a retired atom's file are now retried on the next run like new files, instead of staying behind the database until the page changes again; the summary reads \"N file(s) rolled back; the next run writes them again\". The rollback runs under the commit lock and takes its files out of the pending write-through ledger, so a later hand edit at one of those paths is never swept into a gbrain commit; when the lock stays busy the files are left for that writer's commit." },
  { since: '0.60.708.0', id: 'owner_repair_file_restore_7960', text: "On an unmanaged repository brain, `gbrain repair provenance --apply` or `gbrain trust backfill --repair-unknown-markers` whose database write fails after the page file was written now puts the file's previous bytes back, and when the write had been committed on a hardened checkout, commits that restore (`gbrain: restore write-through <slug>`), so a failed apply leaves the file, Git and the database unchanged (#7960)." },
  { since: '0.60.708.0', id: 'protocol_guard_refusal_typed_7777', text: "A write refused during publication by a persistence protocol guard (SQLSTATE 42501) now fails with the guard's own code on its receipt, `writer_upgrade_required`, `writer_not_quiesced`, `unsupported_mutation_protocol` or `writer_coordinator_required` (relationship `unreadable_state` when the database role cannot read the writer state), with `write_error_detail` naming the guard and a suggestion for that refusal, instead of `storage_error` for an unexpected owner exception. `gbrain sources writer status` gives the same step in `recent_failures[].next_action`. Any other permission error is unchanged, and so is the same refusal outside publication (write admission, protocol activation), which still reports `permission_denied`. Every `unreadable_state` refusal (#7780) now reads \"writer state this database role cannot fully read (row-level security hides it or applies to the role, or a singleton row is missing)\", its receipt suggests running gbrain as a role that can read that state instead of upgrading, and `gbrain sources writer status` shows the table in `recent_failures[].error_detail.state`." },
  { since: '0.60.708.0', id: 'door_index_refresh_7717', text: "On a source with `canonical: git`, a page committed with a legacy file mode (100664) no longer gets a mode-only commit when a write leaves its bytes unchanged, and with `core.fileMode=false` a write of it commits the page as 100644 (before, Git refused the rebuilt tree and the write failed `git_unavailable`). A write replayed after its commit landed and refused `git_index_conflict` because someone staged the page meanwhile now says HEAD already holds its bytes, instead of that it committed nothing. The index refresh after a door commit removes the index copies (`index.gbrain-<pid>-*` in the git directory) a killed gbrain process left behind, and on Windows retries a briefly refused rename of the index before it reports that the commit landed but the index was not updated." },
  { since: '0.60.708.0', id: 'stored_root_predicate_7646', text: "Stored paths (`sources.local_path`, `sync.repo_path`) are judged absolute by one rule in sync, `config set sync.repo_path`, write-through, `gbrain sources set-path --clear` and doctor. On Windows only a drive path (`C:\\...`) or a UNC share counts: a root-relative `\\brain` or `/brain`, which names a folder on whatever drive gbrain runs from, is refused by sync (`sync_anchor_relative`) and cleared by `--clear` like `.`. Doctor's `default_source_local_path` now warns when the `default` source's own path is absolute only on another operating system (a Windows drive path read on Linux or macOS), where it reported ok. A page or fact write whose stored root is not absolute on this host records the database-only reason `relative_root` (it was `no_repo_configured` or none)." },
  { since: '0.60.708.0', id: 'sync_anchor_relative_jobs_7646', text: "A queued `sync` job for a source whose stored path is not absolute on this host completes as a skip (`reason: sync_anchor_relative`, with the ask-the-user fix) instead of failing and using up its attempts. `gbrain sync --all --json` gives such a source's entry `code`, `why` and `fix` beside `error`. With a stored `.`, `gbrain sync --repo ./` is refused like `--repo .`. A relative `sync.repo_path` behind a `default` source with no path no longer lets an explicit `--repo` advance default's last synced commit. `gbrain dream --json` puts a failed phase's ask-the-user fix in its `cycle_failed` envelope." },
  { since: '0.60.708.0', id: 'conversion_root_owner_7956', text: "`gbrain sources canonical <id> --to git` refuses a registered root it cannot read (gone, unmounted, a file, no permission or a symlink loop) with `source_root_unreadable` (reason and fix) instead of a raw filesystem or Git error, and an archived or re-registered source refuses `owner_unavailable` before the Git checkout check instead of `git_checkout_required`. An apply whose source was returned to mixed (`--to mixed`) while it ran reports `incomplete` with a message that the source is mixed, never `converted` (#7956)." },
  { since: '0.60.708.0', id: 'stuck_recovery_strict_followup_7715', text: "On a git-canonical (strict) source, `gbrain repair stuck-recovery --keep disk` now says the kept bytes are an uncommitted edit at the file's path and hands off to commit then sync (`gbrain git commit-push --path <checkout> -m \"<message>\" -- <path>`, or `git -C <checkout> restore -- <path>` to discard, then `gbrain sync --source <id> --no-pull`; verify with `git status --porcelain` then `gbrain sync status --source <id> --json`), with an ask-the-user `fix` in the item detail, instead of a database-side `sources reconcile`. Mixed sources keep the reconcile follow-up (#7715)." },
  { since: '0.60.708.0', id: 'url_clone_fences_held_preview_7910', text: "`gbrain repair url-clone-fences` lists a held file (for example `visibility_noncanonical`) once, as an apply item, and no longer also counts it as a residual; its preview says the restored file equals HEAD, so sync does not screen it again and the page changes once an upstream fix is pulled and synced (it no longer claims sync holds the file) (#7910)." },
  { since: '0.60.708.0', id: 'streamed_put_visibility_wording_7881', text: "On a brain without managed persistence, `gbrain put --file` and `gbrain capture --file` of a page over the single-string ceiling that asks for `visibility: private` in a spelling page privacy does not read refuse `visibility_not_applied` with the page-write message a smaller put gives (nothing was written; write `visibility: private` on its own frontmatter line), not the import hold's \"sync or import the file again\" (#7881)." },
  { since: '0.60.708.0', id: 'git_durability_refusal_no_side_effects_7634', text: "`gbrain sources writer git-durability <source>` without `--dry-run` now checks `--admin-intent writer_git_durability` and `--expected-state` first: a missing, wrong or stale approval refuses (`writer_admin_intent_required` or `writer_admin_state_changed`) before the token file is read and before anything changes. It used to rewrite the durability block in `AGENTS.md`/`RESOLVER.md`, wire the `--pat-file` credential and retry parked pushes first. After an approved apply, `agents.commit` now names `gbrain git commit-push --path <root> -m \"<msg>\" -- <file>` instead of plain git." },
  { since: '0.60.708.0', id: 'parked_push_hidden_page_7110', text: "`gbrain sources writer retry-effects <source> --parked-pushes` (and `git-durability --pat-file`) no longer stops the whole run when one parked request's remote writer can no longer see its page (it became private): that request is listed in `refused` with its `request_id`, code `page_not_found`, the page slug and a read-only receipt command, the other parked pushes are retried, and the run ends `partial` (exit 1). The refused request stays parked; nothing retries it under another authority." },
  { since: '0.60.708.0', id: 'embedding_preflight_abort_7772', text: "An embedding effect whose stop signal fires while its provider call is being admitted (for example a one-shot `gbrain put` exiting) is now retried (`queued`, `embedding_aborted`) instead of failing for good as `embedding_budget_refused`, which blocked writer quiescence and showed in doctor `stale_embedding_effects` until `gbrain repair embedding-effects --apply`. A real budget refusal still fails as `embedding_budget_refused`." },
  { since: '0.60.708.0', id: 'mirror_read_only_legacy_writers_7098', text: "On a brain without managed persistence, a source marked `gbrain sources mirror-readonly` is now left untouched by the legacy disk writers below (#7098): `sync --full` no longer re-exports never-committed database pages into its checkout, `brainstorm --save`, page write-through, timeline entries and fact fences keep the write in the database (write-through and timeline report `skipped: mirror_read_only`), `forget` expires a fenced fact in the database without rewriting the file, and the extract cycle neither fences its database-only facts into the file nor counts them in its legacy-row guard. An owner trust repair (`gbrain repair provenance`, `trust backfill`) lists such a page `needs_review` with detail `mirror_read_only` instead of rewriting its file. The dream cycle leaves such a checkout alone too: its reverse-written synthesis, patterns and cycle-summary pages stay in the database (#8935). Before, only managed publication honored the flag, so these writers gave the mirror local changes that could stop its `git pull --ff-only`." },
  { since: '0.60.708.0', id: 'copied_root_fix_names_self_transfer_7671', text: "A managed write refused `recovery_required` because a source's checkout is a new directory at its recorded path (a copied or restored brain, detail `physical_root_directory_changed`) now carries the relocated-root self-transfer as its `fix` (#7671): `gbrain sources writer transfer prepare <source> --self-transfer --confirm-relocated-root` with its admin intent, then the accept as `fix.then`, a host-admin step (`next: tell_user_to_run`), on a put_page receipt too, where `fix` used to point at the write receipt. Nothing is re-stamped automatically; the write still refuses until the self-transfer runs." },
  { since: '0.60.708.0', id: 'door_landed_replay_gst2517', text: "On a source configured `canonical: git`, a write whose door commit landed in Git and whose database transaction then failed before committing (an owner exception after the commit) is now replayed by its owner instead of ending `failed` / `storage_error`: the replay finds its change already committed and records it without a second commit. A `forget` caught there now records its withdrawal, so the fact turns inactive and remembering the same claim is refused `fact_withdrawn`; before, the fact stayed active until a sync, no withdrawal was recorded (so the claim could be remembered again) and the reply said nothing was saved. A replay that fails as well ends failed with the commit named on its receipt (`landed_before_row`), and a `remember` or `forget` reply then names that commit instead of saying nothing was saved. `gbrain repair failed-writes` lists a refused `forget` as a caller write to resubmit instead of one the next dream cycle produces again." },
  { since: '0.60.708.0', id: 'requester_scope_gst363', text: "On a brain that serves several people (two or more enabled members, or config `access.serves = several`; a brain pinned `access.serves one` never does), a remote read through a connection bound to no member (an access token, an OAuth client, or a stdio server with no member binding) is now refused with `requester_scope_required` before any work; `whoami`, `get_brain_identity`, `get_status_snapshot`, `search_modes`, `get_health` and a non-admin key's own `get_job` / `wait_job` still answer. A connection that existed when the brain started serving several people (config `access.serves_since`, set once, or this upgrade) reads for 14 more days with `_meta.access.requester_scope` naming the date and the fix; one created later is refused at once. Bind each connection to the person it serves: `gbrain auth rescope --token <name>|--client <id> --member <id>`; a stdio harness only one person uses, `gbrain setup claude-code|codex --stdio-member <id>`; a harness several people talk to, one `--member` key per person over `gbrain serve --http`. A shared agent names the person per call (`--may-act-for`), and `--reads-unscoped --yes` marks one credential to read unscoped on purpose. `gbrain auth create` and `gbrain auth register-client` refuse an unbound credential on such a brain (`credential_scope_required`); `gbrain doctor` fails `unscoped_shared_reads` per unbound credential and `gbrain post-upgrade` lists them. `gbrain doctor` also fails `shared_stdio_binding` when `mcp.stdio_member` is set on a host where OpenClaw or Hermes is installed and the brain serves several people; a `hermes` on PATH counts as Hermes only when it is a script. Hosted brains set `access.requester_scope_enforce false`, which turns every refusal into the notice. Member-bound credentials (the owner's included), attested calls, a one-person brain and the local CLI see no change; writes are not affected." },
  { since: '0.60.710.0', id: 'writer_fence_fail_closed_7636', text: "Since v0.60.474.0 (#7636, migration v278), a Postgres role that row-level security hides gbrain's writer state from (the `persistence_brain` row; on a managed brain also the `git_canonical_brain` row, a source row while any source is Git-canonical, or the page behind a tag, timeline entry or take) is refused with `writer_coordinator_required` (relationship `unreadable_state`) on every guarded write, unmanaged brains included, where such writes used to pass as unmanaged. Run gbrain as the table owner, a role that bypasses RLS, or a scoped role whose policies cover those rows (docs/ENGINES.md#writer-protocol-fences)." },
  { since: '0.60.711.0', id: 'propose_takes_rejected_memory_7299', text: "The dream cycle's `propose_takes` phase no longer puts a claim back in the review queue after you rejected the same claim text on the same page (#7299). Before, any edit to the page re-extracted it and the rejected claims came back as new proposals. A reworded claim is still proposed; the run reports how many it dropped as `rejected_claims_skipped`." },
  { since: '0.60.711.0', id: 'grade_takes_auto_resolve_7542', text: "`gbrain config set cycle.grade_takes.auto_resolve.enabled true` now does what it documents (#7542): the dream cycle's `grade_takes` phase applies a verdict with confidence 0.95 or higher (3/3 at 0.85 or higher on the ensemble path) to the take. Before, the key was ignored and every verdict stayed review-only. Unset or false is unchanged: verdicts wait for review in `gbrain takes grades`." },
  { since: '0.60.711.0', id: 'dream_write_deferral_w3', text: "A dream purge or consolidate write that was accepted but is still pending after its publish wait no longer fails the phase: the phase warns `dream_write_deferred` with the receipt id, and the next pass reads that receipt before it submits anything for the source (committed clears it; a failure is reported with its real code). After 3 passes still pending, doctor `dream_write_deferred` warns with `gbrain write-request -- <id>`. `gbrain config set dream.write_deferral.enabled false` restores the failing phase." },
  { since: '0.60.711.0', id: 'synthesize_no_candidates_w3', text: "A dream synthesize window where every transcript is already synthesized now returns before triage, the manifest context and the child queue, with `details.reason: no_candidates` and the cooldown stamped. Synthesize deaths also count per transcript under `dream:synth-v2:@file:<source>:<file>` once they span two content keys, so a transcript that grows between dying runs is refused after 3 deaths in 24 hours like any other key, and `gbrain dream reset-key` now accepts every key `--list` prints, `dream:phase:` keys included." },
  { since: '0.60.711.0', id: 'embedding_restamp_w3', text: "The maintenance cycle's embed phase now first stamps the current embedding signature on pages whose every chunk already holds a current-model vector, up to 500 pages a run, with no provider call; a page edited or re-embedded during the stamp is left for the next run. Three failed runs in a row warn as doctor `embedding_restamp_stalled`. `gbrain config set embed.restamp.enabled false` turns it off. Health's embedding coverage now counts live pages only, so chunks kept on a soft-deleted page no longer lower it." },
  { since: '0.60.711.0', id: 'doctor_foreign_skills_folder', text: "`gbrain doctor` no longer grades a skills folder it found by walking up from the current directory unless gbrain installed it (a skills.lock.json, a valid manifest.json or the skillpack block in its resolver file): resolver_health and skill_currency report \"not a gbrain skills folder (<path>)\" as info, so an agent's own skills folder no longer lowers health_score or fails doctor. Pass --skills-dir (or set GBRAIN_SKILLS_DIR / OPENCLAW_WORKSPACE) to grade it as before. Agent crons should page on the new `gbrain doctor --alert` (exit 17 act, 18 unknown), not on health_score." },
  { since: '0.60.711.0', id: 'upgrade_installs_no_autopilot', text: "An upgrade no longer installs autopilot on a Postgres brain that has none, even with sync.repo_path set: the v0.11.0 migration's Phase F is skipped (reason not_installed), prints the install command and records it, and `gbrain doctor` shows it as a minions_migration line until you run it. An autopilot already installed for the brain is reinstalled as before." },
  { since: '0.60.711.0', id: 'session_lane_budget_gbra133', text: "New read-only `gbrain doctor` check `session_lane_budget` counts this database role's connections across every gbrain process (by process kind and host, from the `gbrain <kind>:<pid>:<nonce>` connection name) and warns at 80% of the limit, naming the kinds holding the most. Behind a Supabase pooler, set `GBRAIN_SESSION_LANE_LIMIT` to the project's `pool_size` to compare (Postgres cannot read it); without it the check reports the counts only. Without a pooler the limit is `max_connections` less the reserved slots. Not applicable on PGLite." },
  { since: '0.60.711.0', id: 'github_item_webhook_backlog_8799', text: "A GitHub webhook for an item event (issue, pull request, comment, review, check) now answers HTTP 429 `webhook_backlog_full` with `Retry-After: 30` when 50 item jobs are already waiting for that source and none of them covers the event; it used to answer 202 with another item's job while the event was dropped. GitHub does not redeliver a 429 on its own: redeliver it from the webhook's Recent Deliveries, or let the next sweep or `gbrain sync --source <id>` catch it." },
  { since: '0.60.711.0', id: 'webhook_capture_no_default_fallback_gst2113', text: "A webhook capture (`POST /ingest` and its `ingest_capture` job) whose credential's write source is archived, unregistered or removed before the capture lands now fails the job with `source_changed` (`detail: webhook_source_unavailable`) and writes nothing. Before, it was written under `default`, a source the credential may not be granted, and could replace a page there. Restore the source and run `gbrain jobs retry` on the job. Captures that do not come from a webhook keep the `default` fallback." },
  { since: '0.60.711.0', id: 'code_rechunk_module_elixir_8128', text: "Code sync re-chunks TypeScript, TSX, JavaScript, Python, Ruby and Elixir files once (a per-language chunker revision): top-level code with no named definition (anonymous default exports, top-level `if`/`for`/`try`, Python's `__main__` block) becomes `<file>::__module__` chunks with call edges, and Elixir modules and functions become named definitions that `code-def` and `code-callers` find. The sync cost gate prices only those files." },
  { since: '0.60.711.0', id: 'db_link_child_folder_6983', text: "On the DB link path (`gbrain extract links --source db` and automatic link backfills), a `.md` link with a folder and no `./` or `../` prefix (`[x](notes/a.md)`) now resolves against the linking page's folder first, then its parent folders, then the brain root, matching `--source fs`. Where both a child page and a root page exist, the edge now points at the child." },
  { since: '0.60.711.0', id: 'remote_think_host_model_gbra437', text: "A remote `think` (MCP, HTTP or a thin client) now runs on the brain host's think model (`models.think`, then `models.default`) unless the host lists the requested `model` in the new `think.remote_models` key (comma-separated, empty by default). An unlisted model, or a listed one the host cannot run, no longer fails the call with the explicit-model error: the host model answers, `warnings` carries `MODEL_OVERRIDE_IGNORED:not_allowed` or `:unusable`, and the result carries a `model_override_ignored` notice. Remote `rounds` runs one round. The local CLI `--model` is unchanged, and a keyless brain answers as before." },
  { since: '0.60.711.0', id: 'physical_root_moved_8625', text: "On a managed brain, a checkout moved to a new path (or whose parent folder was renamed) is now named: `gbrain sources add`, `gbrain sources set-path` and `gbrain sources writer claim` refuse with `recovery_required`, detail `physical_root_moved`, naming the recorded path, the worktree and the commands that bring it back, instead of a generic identity error (add, claim) or detail-less `source_checkout_missing` (set-path). Their `--dry-run` now refuses as the real run does: before, the add, claim and set-path dry runs of a moved checkout, the add and claim dry runs of a folder holding a copied ownership stamp, and the set-path dry run of a missing checkout exited 0. Nothing about ownership changed; the dry runs still write nothing." },
  { since: '0.60.712.0', id: 'moved_pages_fold_gst2584', text: "gbrain repair file-drift --held no longer offers a delete or a recreate for a page whose file moved while its deletion was held: it lists the page as moved_to <slug> with the new gbrain repair moved-pages --source <id> --slug <old-slug> fold command, and --prefer file skips it. A file that names the page type gbrain-base 1.0.0 gave its path, equal to the type copy an older gbrain stored in the page's frontmatter, now keeps the type a later schema pack gave the page on import, and the import records the rename as a legacy_type retype stamp; before, the next edit read the old type back into the page." },
  { since: '0.60.712.0', id: 'folder_holding_page_gst2492', text: "On a source whose pages are canonical in Git (`canonical: git`), a fact for an entity with no page under a folder access rule is no longer kept in the database only: it is held on the holding page of the entity's folder (`partners/memory/unattributed` for `partners/acme-example`), in Git (or database-only where the folder is) with exactly the readers the entity's page would have. The reply names that `page`. `gbrain access rule add` previews the held facts a new rule covers (`held_facts_moving`) and its apply moves them off their holding page (`held_facts`), as do `gbrain access apply`, `gbrain access resume` and a sync that applies a rule from Git; the moved rows and those entities' struck rows also leave that page's saved versions in the database (`held_versions_editing`, `held_versions_edited`), and Git history is not rewritten. A saved version stored in segments is not edited: the preview names how many (`segmented_versions_not_edited`) and the apply says `complete: false`. A move still pending is reported with its request id (`pending`, `HELD_FACT_PENDING`), not counted as moved. A held fact is now also hidden from a caller who cannot read its holding page, even under a rule with `covers_derived: false`. `gbrain repair facts-home` writes such facts to their folder's page and lists as `folder_restricted` only an exact page rule or unreadable rules. A `remember` for a page-less entity under an exact page rule now refuses `git_home_required` with a fix that creates the page, and one whose access rules this database role cannot read refuses `access_policy_pending`; both wrote the fact to the database before. An existing page whose slug ends in `/memory/unattributed` is now read as a holding page: a row with no `entity` cell becomes a fact with no entity, a row naming an entity in the page's own folder becomes that entity's held fact, and a row naming an entity of another folder is a fence problem. Non-strict sources and brains with no Git repository are unchanged." },
  { since: '0.60.713.0', id: 'stuck_head_released_9227', text: "On a PGLite brain, the next gbrain process that opens the brain now releases at once every write claim an earlier, exited process left running and runs those writes again, instead of leaving later writes to the same source pending for the rest of the claim's lease (30 s, or about 6 minutes while publishing). `gbrain sources writer status` reports a claim whose owner has provably exited (that case on PGLite, a dead process on the same machine on Postgres) with `owner_exited: true`, `resumes_on_its_own: true`, `owner_live: false` and `next.code: claim_owner_exited`, where it said `claim_running`." },
  { since: '0.60.713.0', id: 'receipt_git_state_live_9227', text: "A write receipt read after the write (`gbrain write-request`, `get_write_request`, `list_write_requests`) for a page on a checkout that is not `canonical: git` now takes `persistence.git_state` from the page's Git effect: `committed` with the commit in `persistence.git_commit`, or `superseded`, `skipped`, `failed` or `retrying` with `persistence.git_reason`, where it always said `queued`. Stored receipts are not rewritten; the stored `outcome` still says `queued`." },
  { since: '0.60.713.0', id: 'label_repairs_hold_refusals_gst2603', text: "gbrain repair visibility and gbrain repair private-labels now ignore stamps gbrain keeps only in the database (a pack-renamed type, the validate: false grandfather stamp, a legacy_type retype record) when they edit a page's label line, so those pages are labelled. A page whose file still differs in a real key, or whose label line cannot be edited as one line, is held by the preview with the blocking key and its next step and is left out of the approved set. A page that starts refusing after the preview is declined with label_edit_refused, nothing is written for it, the run exits 0 and it no longer counts toward item_failures_systemic. Their previews, and those of gbrain access rule add and import, also list same-slug pages in other sources that the change leaves readable (open_twins), with their count and the command that covers them; nothing changes those pages for you." },
  { since: '0.60.713.0', id: 'corpus_segmented_entity_9279', text: "Captured session files whose facts name a large entity page (one stored in segments, over about 1 MiB) are now extracted: facts inferred from a mention of that page were refused after the model call, so those files were retried five times and then stopped. The first sweep after this upgrade retries each file stopped that way once, at the cost of one model call per stopped window, with no command needed. From now on a refusal that retrying cannot change stops its window after one paid attempt instead of five, retention keeps the session file instead of deleting it at the un-ingested limit, and gbrain doctor (memory_writeback) counts these files as held. gbrain sweep --retry-failed --apply still retries them by hand." },
  { since: '0.60.715.0', id: 'skillpack_update_untouched', text: "Installed skills can now take gbrain's current version whole when you never edited them. `gbrain skillpack scaffold` (including `--harness` installs) and every update record the sha256 of each skill file it installed in `~/.gbrain/skillpack-state.json` (schema `gbrain-skillpack-state-v2`; an older gbrain refuses that file instead of dropping its records). Preview what would change with `gbrain skillpack reference --all --update-untouched --dry-run`; a skill with any edited file, a pinned skill (`gbrain skillpack pin <skill>`) or one with no recorded hash is skipped with a reason and a diff. Every update is journaled under `~/.gbrain/skillpack-backups/` and undone with `gbrain skillpack restore <id>`. `gbrain upgrade` writes no skill files; nothing runs on upgrade." },
  { since: '0.60.715.0', id: 'claude_cli_setting_sources_8342', text: "On Claude Code 2.1.314 or newer, the claude-cli provider now runs its child with `--setting-sources \"\"`, so your own `~/.claude/CLAUDE.md`, memory and `settings.json` no longer steer gbrain's background claude-cli calls. The subscription login is kept, but `settings.json`'s `env`, `apiKeyHelper` and permission rules no longer reach the child either. `GBRAIN_CLAUDE_CLI_USER_SETTINGS=1` (shell or ~/.gbrain/.env) loads them again. Older CLIs are unchanged." },
  { since: '0.60.715.0', id: 'unattended_maintenance_doctor_gbra438', text: "`gbrain doctor` has a new check, `unattended_maintenance`, which reads the free-upkeep record `maintenance.last_run`: it warns (and so can lower doctor status from healthy) when no upkeep run is recorded on a brain older than 48 hours, when the last run is older than 48 hours, or when one step failed three runs in a row; the fix is `gbrain maintain --unattended`. Upkeep turned off (`maintenance.auto false`) or owned by an autopilot reads ok. New commands: `gbrain maintain --unattended`, `--status` and `--purge` (preview, then `--yes --expect <hash>`)." },
  { since: '0.60.715.0', id: 'bookkeeping_gc_phase_gbra438', text: "The dream cycle has a new phase, `bookkeeping_gc`, after `purge`: it now does the retention GC that `purge` used to do (op checkpoints, brainstorm checkpoints, batch-retry audit files, volunteer events, decision receipts, applied captures, retrieval feedback), with the same retentions. `gbrain dream --json` reports those counts under `bookkeeping_gc` instead of `purge`, whose details keep only sources, pages and orphan clones; `--phase purge` no longer runs the GC." },
  { since: '0.60.715.0', id: 'autopilot_refusals_structured_gbra438', text: "`gbrain autopilot --install` refusals (a PGLite brain without --force, no repo path) now go through the agent error contract: codes `autopilot_pglite_daemon` and `autopilot_no_repo`, a why, a fix and `--json` output, instead of a bare line on stderr; PGLite and repo-less users are pointed to `gbrain maintain --status`." },
  { since: '0.60.715.0', id: 'cycle_skip_text_gbra438', text: "A dream cycle phase skipped for want of a checkout no longer says (postgres/remote engine), which was wrong on PGLite: the summary is now: requires a local brain directory; this brain has no on-disk checkout; pass --dir <path> to run filesystem phases. The reason code `no_brain_dir` is unchanged." },
  { since: '0.60.715.0', id: 'cycle_freshness_keyless_consent_gbra438', text: "On a brain with no chat or embedding key, the `cycle_freshness` doctor fix (`gbrain dream --source <id>`) now asks no paid consent (`consent: []`, so `next: run`), because no phase it runs can spend." },
  { since: '0.60.715.0', id: 'serve_idle_upkeep_gbra438', text: "An open `gbrain serve` (stdio or HTTP) now runs the free unattended upkeep (`gbrain maintain --unattended`: link and timeline extraction, stale-page checks, free repair lanes, bookkeeping GC, and on a keyed brain the capped embedding step) while it is idle, at most once every 24 hours per brain, in slices of about 3 seconds that stop when a tool call arrives. It never deletes a page. `maintenance.auto false` or `GBRAIN_SWEEP=0` turns it off; an autopilot brain is left to autopilot. The record it writes is `maintenance.last_run` with runner `serve`." },
  { since: '0.60.715.0', id: 'serve_http_idle_timer_gbra438', text: "HTTP `gbrain serve --http` now has an idle timer: it counts an MCP POST as foreground work and runs the idle upkeep only when no request is in flight, aborting the upkeep slice when one arrives. Before, only the stdio server had idle work." },
  { since: '0.60.715.0', id: 'init_upkeep_line_gbra438', text: "The first-run settings block printed by `gbrain init` and `gbrain setup <harness>` (and its `--json` decisions) now includes an `upkeep` decision when it shows other settings: upkeep runs while an agent has `gbrain serve` open and idle, on by default, turned off with `gbrain config set maintenance.auto false`. New commands: `gbrain maintain --schedule` (opt-in launchd, systemd or cron job every 6 hours, preview with `--dry-run`, asks consent) and `--unschedule`." },
  { since: '0.60.716.0', id: 'chronicle_events_trust_cap_9284', text: "Legacy Life Chronicle event pages (captured_via: life-chronicle:auto) are now capped at agent_written and at the tier of their depth page when gbrain trust claim-sources lifts a source, so they no longer read as your own notes; rows a claim already lifted change only when you run gbrain trust claim-sources --relower (preview with gbrain trust claim-sources --relower --dry-run first, and add --source <id> for a source whose claim has ended), and gbrain doctor counts them." },
  { since: '0.60.716.0', id: 'audit_secrets_escaped_encoded_8265', text: "The opt-in high-entropy assignment detector now also catches a credential whose key quote is escaped (`{\\\"password\\\":\\\"…\\\"}`, JSON inside a JSON string, with up to three backslashes) and one after a URL-encoded separator (`password%3D…`, `token%3A…`). The value stops before an escaped closing quote and, after an encoded separator, before the next `%26` parameter; a URL-encoded URL value is treated as a reference, not a secret. `gbrain doctor` asks once for a fresh `gbrain transcripts audit-secrets` run: it is read-only, makes no model or network call, and on a 5 MB synthetic transcript took about a third of a second. Transcripts imported from now on redact both shapes. Pages imported before are not rewritten; the audit lists the ones that hold such a line as affected." },
  { since: '0.60.717.0', id: 'holding_page_versions_gst2497', text: "A holding page (memory/unattributed, or a folder's <folder>/memory/unattributed) now keeps only its newest five saved versions, whatever their size, as large pages already did. `get_versions` and `gbrain revert` see only those five. Every fact row on the page is kept, the page itself still holds every row, and Git keeps every state of the page where the brain has a repository. An older holding page sheds its extra versions in batches of at most 100 on its next saves, so nothing runs on upgrade. Once a version is removed, an `as_of` read of the page reports incomplete history, and `gbrain repair unwithdrawn-facts` lists that page's candidates as ambiguous: restore them with `--include-ambiguous` and the hash of that preview. Nothing to run." },
  { since: '0.60.717.0', id: 'owner_room_marks_gst2639', text: "A harness can now declare the group chat an answer goes into (the X-Gbrain-Room header, request-level _meta.room, or a room tool argument once whoami shows features.room). The caller's read is unchanged; every page and fact in the answer is marked room_access with whether the people in that chat could have read it, and the room_above_level notice tells the agent to keep those items out of the reply. A call with no room is unaffected. With mcp.strict_params set to reject, every tool schema now also declares the optional room argument. See docs/guides/rooms.md." },
  { since: '0.60.718.0', id: 'managed_push_scan_every_publish_gst2650', text: "Every push gbrain makes is now scanned for secrets with no opt-out: `commitAndPush` no longer has an unscanned mode, so a push handed over from a busy publish lock is scanned too. Only the commits the remote lacks are read, and a missing remote-tracking branch is fetched first instead of scanning the whole history. In a managed root below the repository's top level, a commit changing that root's own `.gbrain-scan-allow` is held like one at the top level, and its path globs match paths relative to that root. A strict (canonical: git) source's commit whose files a Git clean filter changed is scanned instead of trusted, and so is one made before this release that is still unpushed; either is still pushed when the scan finds nothing. Git replace refs no longer change what a page-write commit holds. A false positive in an unpushed commit holds the push with `publish_secret_found` naming the file, line and rule, never the value: add its fingerprint to `.gbrain-scan-allow`, then run `gbrain sources writer retry-effects <source> --parked-pushes`, or the push fix `gbrain doctor` names." },
  { since: '0.60.718.0', id: 'strict_fallback_refusal_gst2635', text: "On a source whose pages are canonical in Git (`canonical: git`), a fact the Google loops extraction (or any writer that keeps a fallback entity, writeSingleFact) finds for an entity with no page that an exact page rule names is now refused `git_home_required` (reason `facts_lane`) before anything is stored, with a fix that creates the entity's page; before, it was stored in the database only, with no file in Git, or refused with a message naming memory/unattributed. When the access rules cannot be read the write refuses `access_policy_pending` (retry), and that refusal's message now names the entity, for `remember` too. The loops job still records the loop and logs the refusal code with the entity's page; nothing is stored for that fact. Facts stored the old way are not changed: `gbrain repair facts-home` lists them as `folder_restricted`. Sources that are not strict and brains with no Git repository are unchanged." },
  { since: '0.60.719.0', id: 'access_first_import_history_gst2638', text: "A folder-rule edit (gbrain access rule add, rm, revert or import) on a git-backed source that has no folder-rule revision yet now refuses before writing anything, with access_policy_history_unreadable, when its checkout is shallow or a partial clone missing the Git objects of its folder-rule history; it used to commit the file and leave the whole source reading as nobody. When you hit it, run git -C <source root> fetch --unshallow (for a partial clone, git -C <source root> log --first-parent -p HEAD -- .gbrain/access.yml, which fetches every version), then rerun the same gbrain access rule command; nothing was written, so the source keeps its current reads meanwhile. A first edit on a source with no folder-rule history no longer reads the whole source as nobody while it applies. An edit whose result state is invalid now exits 1 instead of 0. Unchanged: a plain gbrain sync of a shallow checkout whose commits already hold folder-rule history still fails closed as before, reading the whole source as nobody because the history cannot be replayed; recover the same way, git -C <source root> fetch --unshallow, then gbrain sync --source <id> --no-pull." },
  { since: '0.60.719.0', id: 'room_cli_think_writes_gst2639', text: "`--room <list>` now works on every gbrain operation command (`gbrain query \"plan\" --room alice-example,group:team-a`). The command prints what it always printed; the room only adds marks. With --json every item carries room_access and the document carries _meta.room, and a list answer becomes { results, _meta } only when --room is given. Without --json, stderr adds a [gbrain room: ...] summary. The local CLI marks the brain owner's view (gbrain access owner set) or the member --as names; with no owner every item is unknown (unbound). A trailing --room with no value marks every item unknown (invalid) with the degraded stamp and exits 0. A running gbrain serve that owns a PGLite brain marks delegated answers, and a thin client sends the room as _meta.room; an owner or host that predates room marks leaves every item unknown (not_supported). With a room declared, think answers are now marked at the strictest class of everything their synthesis retrieved (unknown when built partly from takes or with no recorded evidence), and put_page and remember mark the page or fact they wrote without a degraded stamp, where before they answered op_not_covered. Calls with no room are unchanged. Guide: docs/guides/rooms.md." },
  { since: '0.60.719.0', id: 'owner_turn_sends_templates_gst2656', text: "New installs get two changed templates. The access-policy template's group-chat rule now says a turn the owner sends, verified by sender identity, is done at the owner's scope exactly as in a private chat, written for the room, with truly private material offered in the owner's private chat and never a refusal; every other member is answered at the group's level, and a member saying the owner wants something is making their own ask. The agent template's red line on messaging third parties now says a send the principal asks for in their own verified message (or through a delegate the principal set up and the host authenticates) goes out as asked, in any chat and to any recipient, with no approval phrase and no draft-first step; the agent still never messages anyone as the principal on its own initiative, and a request another person quotes, forwards or relays is that person's. The money and deletion red lines are unchanged. Existing installs keep their own ACCESS_POLICY.md and AGENTS.md; to adopt the new wording, copy it from templates/ACCESS_POLICY.md.template and templates/bootstrap/template-repo/AGENTS.md." },
  { since: '0.60.720.0', id: 'storage_shelf_stored_object_type_8894', text: "The bundled `gbrain-base-v2` schema pack (the `init` default, also inherited by `company-brain`) is now version 1.6.0 and declares the `stored-object` page type the storage verbs stamp on every storage shelf card, so registering, adopting or importing a card no longer prints a `page_type_undeclared` notice, doctor `schema_pack_consistency` does not warn about the shelf, and `unify-types` never retypes cards to `note`. Existing pages keep their type; no data changes. The active pack identity reads `gbrain-base-v2@1.6.0+<hash>`." },
  { since: '0.60.721.0', id: 'derived_origin_carry_private_gst2689', text: "Deleting a page that keeps other pages private now writes a visibility: private label on each page that was private only because of it (a summary whose derived_from names it, an atom extracted from it, a synthesized concept built from such an atom), before the deleted page's row is removed. On a brain with Git the derived page's file gains that one label line. The label stays if you restore the deleted page later. If a label cannot be written, the purge keeps the deleted page soft-deleted and gbrain doctor reports it as derived_origin_parked with the page that blocks it; an explicit gbrain delete --purge then returns purge_held instead of purging." },
  { since: '0.60.722.0', id: 'owner_remote_private_writes_gst2091', text: "The brain owner's own remote agents can now change private pages. A credential bound to the brain owner (gbrain access owner set) that has write scope and speaks for itself (no audience, not an attested call, not a subagent job, no slug fence) may rewrite, edit, append to and relabel a page marked visibility: private that it already reads, through put_page, edit_page and append_page, and through put_pages and staged uploads (begin_page_upload and commit_page_upload), which write the same pages; before, these writes answered page_not_found. A put_page that leaves out visibility or readable_by keeps the stored ones, an empty visibility counts as left out, and a page private only through a privacy alias, a pinned question, a derived type or a private origin is saved as visibility: private (a pinned question keeps its marker) by any of these writes that states no visibility; the change is recorded under the owner's credential. Everyone else is refused exactly as before: other members, unbound tokens and OAuth clients, attested calls, the owner's credential asserting a shared room, the owner's credential without write scope, and any write to a page whose readable_by or folder rule leaves the owner out. delete_page on a private page, and any write to a soft-deleted private page, stays refused, and a credential fenced to slug prefixes, even after the write was submitted, gets no owner widening. An owner who does not want an agent to change private pages gives that agent a credential without write scope (gbrain auth create <name> --member <owner> --scopes read; without --scopes the token gets full access), or binds it to its own member instead of the owner." },
  { since: '0.60.722.0', id: 'guest_notes_gbra504', text: "New guest notes (GBRA-504): a brain can keep what people outside it say in a group chat with your agent, in a guest source that only a listed broker credential writes, once per note. Nothing changes until you run gbrain guests init: a brain without a guest source reads, writes and costs exactly as before, and no grant, privacy label or search scope changes on upgrade. With a guest source, every read that returns a guest note marks it as an outside guest's words (origin guest, trust tier external_untrusted, a guest object in JSON and a warning line in text), guest notes feed no facts, takes, timeline entries or links, and your own CLI cannot write there. You keep a note as your own page with gbrain guests promote <slug> (MCP promote_guest_note, owner only; anyone else is refused guest_promotion_owner_only), after which the broker can no longer delete it (guest_page_promoted). A guest writer can delete only the guest notes it saved itself. Your own tokens and OAuth clients read the guest source only once it is on their read list: gbrain guests grant-owner-clients previews that and --yes applies it, and gbrain doctor --only guest_source checks the whole setup." },
  { since: '0.60.723.0', id: 'access_rule_keeps_owner_gst2698', text: "gbrain access rule add now refuses a reader list that leaves out the brain owner when one is set (gbrain access owner), the same refusal gbrain repair visibility --readers already gives (readers_omit_owner), because such a rule closes the folder or page to the owner's own keys. Add the owner to --readers, or pass --allow-without-owner when the owner should not read it. A group that holds the owner does not count. Rules already in place are not changed, and a brain with no owner set behaves as before." },
  { since: '0.60.723.0', id: 'new_sources_join_default_search_gst2732', text: "A source added with no `--federated` or `--no-federated` choice is now federated (in default search, and readable by connections with no source grant) when the brain serves one person: `access.serves` reads one, `brain.audience` classifies personal and the client is not thin. Otherwise it stays unset as before, and `sources add` and `sync --source <id>` print the `source_not_in_default_search` notice with `gbrain sources federate <id>` as the fix (asking the user first on a shared brain). Existing sources are not changed. Adds from a remote MCP caller keep the old default." },
  { since: '0.60.723.0', id: 'plain_folder_sources_gst2732', text: "`gbrain sources add <id> --path <folder>` no longer needs `--force` for a plain folder outside any git repository: it registers as a plain directory (sync imports its files without Git, a removed file keeps its page). The `not_a_git_repo` refusal now applies only to a path inside a git repository with no committed, tracked content." },
  { since: '0.60.723.0', id: 'install_no_postinstall_gst2732', text: "gbrain ships no postinstall script, so a global `bun install -g` of the stable release no longer ends with Bun's \"Blocked 1 postinstall\" line and a clone's `bun install` no longer prints \"postinstall skipped\". Nothing it did is lost: every command already refuses on a Bun below the floor, `gbrain setup` applies a new brain's setup migrations, `gbrain upgrade` runs migrations in post-upgrade, and the first command on a brain applies pending schema migrations. New: when upgrade migrations are still pending (after reinstalling over an older brain with `bun install -g`), every command except apply-migrations, upgrade, post-upgrade, doctor, init, setup and serve prints a `migrations_pending` notice naming them, with `gbrain apply-migrations --yes` as the fix." },
  { since: '0.60.723.0', id: 'first_run_connects_then_reports_gst2732', text: "`gbrain init` no longer asks the user to approve connecting gbrain to their agent. The first-run bundle (`first_run_decisions`) now lists the settings in effect and how to change them, with no \"Reply 'defaults'\" question: search mode as applied, automatic saving (`writeback`) shown as in effect `off` with `salient` recommended (it was shown as default `salient` while off), skills and upkeep. Connecting the agent moved out of the bundle into its own `harness_wiring` notice (kind info, actor agent, no consent), because it is an install step. The install docs (AGENTS.md step 3, INSTALL_FOR_AGENTS.md Step 3.5) drop the STOP for every harness: connect first, then relay the settings and the cost matrix in the reply that reports the install. Nothing paid turns on from these settings without a key the user supplied." },
  { since: '0.60.723.0', id: 'resynthesis_hold_6753', text: "gbrain dream no longer re-synthesizes a transcript that keeps growing on every pass. A transcript synthesized within dream.synthesize.cooldown_hours (12 by default) is held until that window passes, and the run reports how many grown transcripts it held (resynthesis_cooldown). A busy transcript is now re-synthesized at most twice a day instead of up to 24 times; the daily spend ceiling is unchanged. An explicit gbrain dream --input or --date run is never held. To re-synthesize sooner, lower dream.synthesize.cooldown_hours or pass --input." },
  { since: '0.60.723.0', id: 'skill_resolver_gate_default_gst2704', text: "The skill resolver now stays quiet when no skill fits. Before, it showed a skills block on almost every message, including ones that need no skill, because some skill always shared a word with the message. It now leaves the block out when its best match is weak (skills.resolver.top_gate, default 0.6), and a skill you name in the message is still suggested. On a 351-skill public test catalog this cut blocks on no-skill requests from 100% to 11.5% and kept the right skill in the block for 174 of 228 requests that needed one, against 176 before. To tune it, run gbrain config set skills.resolver.top_gate <number>; set it to 0 to get the old behavior back. OpenClaw and Pi pick up the setting on the next gbrain setup <harness> --skill-loading resolve." },
  { since: '0.60.723.0', id: 'thin_client_serve_stdio_bridge_8543', text: "On a thin client (gbrain init --mcp-only), plain `gbrain serve` no longer refuses: it is now a stdio MCP server that relays every call to the brain host with the stored OAuth client's grant, opens no local database and adds no access. A harness entry that runs `gbrain serve` on a thin client now connects to the remote brain instead of exiting with requires_local_engine. `gbrain serve --http`, `--access` and the other host flags still refuse there. `gbrain doctor` on a read or read+write client now reports the missing admin scope as expected (ok) instead of a warning that suggested re-registering with admin." },
  { since: '0.60.723.0', id: 'guest_sources_scoped_role_fail_closed_9354', text: "Brains whose gbrain process connects to Postgres as a scoped row-level-security role now need that role to read the guest_sources table. Before, such a role read it as empty, so guest-source checks passed every write as if no source were a guest source. Now a role that row-level security keeps from reading guest_sources is refused with writer_coordinator_required (unreadable_state, state guest_sources) on page, fact, take and timeline writes, because it cannot tell a guest source from an ordinary one. The table owner, a role that bypasses row-level security, and PGLite brains are unaffected. To keep writing, give the scoped writer the SELECT policy on guest_sources from the maintainer recipe in docs/ENGINES.md (derived-state maintainers)." },
  { since: '0.60.724.0', id: 'commit_push_symlinked_source_gst2767', text: "gbrain git commit-push now resolves a named path through any symlinked folder to its real place in the checkout, so a path spelled through a source path that links into the repository is committed instead of refused as outside the checkout, and a leftover .git folder or file that git itself ignores no longer makes a folder count as skipped. Each skipped path carries why next to reason in the JSON detail, and the push log gets a [push] SKIPPED, NEEDS ATTENTION line for it. gbrain embed <slug> refuses a flag it does not take with unknown_flag (exit 2) before asking for spend approval, instead of reading the next argument as a page. gbrain sources writer git-durability --enable returns agents.commit_argv, the exact gbrain git commit-push command, whenever the durability file it owns is not committed, including an untracked copy an earlier run left. A named folder whose tracked files are staged for removal while still on disk is refused as staged_for_removal, naming --untrack and git restore --staged, instead of as commit_prestaged_paths, and --dry-run reports the same skipped paths and reasons the real run would. A source folder whose .git links to the repository's own .git now commits at its real place in the repository instead of in a copy at the top. gbrain sync no longer creates a repository in a brain folder that sits inside another repository it cannot read." },
  { since: '0.60.724.0', id: 'transcript_secret_rules_gst2768', text: "Imported conversation pages now also redact cookie values (`Cookie:` and `Set-Cookie:` headers, curl `-b`/`--cookie`; names kept), a one-line `.netrc` password, and a value that arrives alone on the line after a key or token label or in the message after any credential label (`password:`, then the password). These rules run only for transcripts; the `sources push` gate and the compiled-context scan are unchanged. Pages imported earlier are not rewritten: doctor's `transcript_secret_exposure` asks for a fresh `gbrain transcripts audit-secrets`, which now lists pages carrying cookie values, `.netrc` passwords and a key label with its value on the next line. It cannot see a value that was sent as its own message, because a stored page no longer marks where one message ends. Three cases still reach the page verbatim, as they do today: a `.netrc` entry written over several lines (`machine`, `login` and `password` each on its own line), a `-b` cookie on its own continued line of a multi-line curl command (what Chrome's \"Copy as cURL\" produces), and a quoted cookie value inside escaped JSON (`sid=\\\"…\\\"`)." },
  { since: '0.60.725.0', id: 'doctor_git_gap_unknown_gbra541', text: "`gbrain doctor` now reads the 800 most recently changed pages of each source in db_ahead_of_git and strict_facts_outside_git, and says how far back it looked; `gbrain sources git-gap <source-id>` still reads every page. A census that runs out of its time budget or cannot run, and in strict_facts_outside_git a fenced fact on a page older than that window, now report warn with health unknown instead of ok, and git_index_lag does the same when it cannot read the lag. An agent that pages on `doctor --fail-on warn` may see these checks warn where they used to pass; run `gbrain sources git-gap <source-id>` for the full count." },
  { since: '0.60.725.0', id: 'setup_codex_backups_gst2779', text: "gbrain setup codex and gbrain setup codex --remove now copy each config.toml or hooks.json they change to a .bak.<timestamp> file beside it before writing, and print the backup path. Nothing else about the setup changes; delete the backups once you no longer need them." },
  { since: '0.60.725.0', id: 'keyless_any_word_fill_gst2762', text: "On a brain with no embedding provider (the default keyless install), search and query now add pages that hold only some of the question's words when the first page of results comes back shorter than the limit. Every row returned before keeps its place, text and score, and the added pages follow them. The added rows pass the same read policy, redirect, superseded-page, evidence and injection checks as any other row, carry keyword_fill: true, and --explain-target says they matched only some of the words. When adding them would change another row, or a check that is on was skipped for them, they are left out; a row from a source on decide.egress.deny_sources is treated like any other row from that source, which today means it is returned and counted as judged. Brains with embeddings search exactly as before, and there is no setting to change." },
  { since: '0.60.725.0', id: 'launcher_records_bun_gst2784', text: "gbrain's hook launcher (<config dir>/hook-launcher/gbrain-hook), which every MCP server entry and hook gbrain setup writes starts gbrain through, now records the Bun that installed gbrain and puts it first on PATH. Before, a Codex session started without bun on its PATH (the desktop app, a launcher, a terminal opened before the shell profile changed) could not start gbrain serve or its hooks, and showed no tools. gbrain post-upgrade rewrites the launcher in place, and gbrain setup codex does the same; no config.toml, hooks.json or trust entry changes. gbrain doctor reports a launcher that records no Bun, or a Bun that is gone. The compiled gbrain binary needs no Bun and its launcher does not change." },
  { since: '0.60.725.0', id: 'notifier_sync_disabled_gst2515', text: "The commit notifier now honours a source's sync setting: a source with sync turned off (config.syncEnabled=false) is no longer synced when HEAD moves, and a retry it owed is dropped. An explicit sync request (a sync trigger or webhook) still runs once; if that run fails, the notifier waits for a new request instead of retrying it. To have commits sync that source again, turn sync back on with gbrain sources set-sync <id> on." },
  { since: '0.60.726.0', id: 'transcript_archive_default_gst2768', text: "On a personal brain the conversation archive is now on: the maintenance pass (the idle upkeep of an agent's gbrain serve, gbrain maintain --unattended or its schedule, and autopilot) writes one redacted page per conversation per local day from your Claude Code, Codex, OpenClaw, Hermes and Grok sessions, plus a day index, into the conversations source, then fills in older days a capped run at a time. To turn it off, run gbrain transcripts archive off (pages already written stay). A shared team brain is only offered the archive and stays off until its owner runs gbrain transcripts archive on. On a keyless brain nothing leaves this machine. With an embedding key, the archived text of new days is sent to that provider to be embedded, like any new page (unattended upkeep caps that at maintenance.embed_daily_usd; autopilot and a managed brain's write coordinator embed new pages as they arrive); older history is written keyword-only and its embedding waits until you see the price with gbrain embed --held --dry-run and approve it. No facts are extracted and no Dream synthesis runs on archive pages. gbrain doctor --only transcript_archive_freshness says whether the archive is keeping up." },
  { since: '0.60.731.0', id: 'stable_important_three_classes_gst2818', text: "The stable channel now moves within a day only for a security fix, a data-loss fix or a fix for a regression in a release that is already on stable. Everything else, a fix that only unblocks one setup included, waits for the weekly move; if you need such a fix sooner, install its release by tag (docs/STABILITY.md, \"Pinning a version\")." },
  { since: '0.60.732.0', id: 'owner_purge_tombstones_survive_9469', kind: 'fix', text: "A page the owner purged while a derived page kept it private now gets its purge records whichever later run removes it (an automatic expiry purge, or a run after a failed or deferred one), on repo brains and on brains without a repository, so a restore no longer brings it back. Restoring a backup now removes the same rows a live page purge removes (write requests, files, derived generation items and their effects), not only the page itself, and stops with purge_replay_incomplete, naming the purge it could not replay, instead of reporting success on a partial sweep. A new doctor warning, purge_mirror, says when recent purges are missing from this machine's purge mirror, so restoring an older backup would not replay them (#9469)." },
  { since: '0.60.733.0', id: 'keyword_skip_rerun_7082', kind: 'fix', text: "On Postgres, a hybrid keyword statement that hit the keyword statement timeout is still skipped by later identical searches in the same serving process (`keyword_arm_failed: skipped_after_timeout`), but the skip no longer always lasts the whole `search.keyword_timeout_negative_cache_seconds` (default 600 s, unchanged, now the longest skip). The serve re-runs the statement once in the background 30 s after the timeout, then after 60 s, 120 s and so on while it keeps failing, with the same scope and the same bound, only when the pool has no waiting query and keeps a connection free for other queries, and one at a time per brain. Its rows are thrown away and it is not recorded as a search. The first re-run that answers ends the skip, so a timeout on a cold cache stops costing keyword results within about a minute of the cache warming. One-shot CLI commands are unchanged." },
  { since: '0.60.733.0', id: 'migration_host_work_owed', kind: 'fix', text: "A migration that stopped three or more runs in a row on a conflict in one or more sources, and recorded that host work is still owed (today only v0.53.0, the shared-skills content migration), is no longer called history once a newer migration completes. gbrain apply-migrations --list, the notice other commands and gbrain serve print at startup, and gbrain doctor (as a warning) now all say the work is still owed and that it does not clear without a person, and they all name the same first step, gbrain apply-migrations --migration 0.53.0 --dry-run --json, which lists each source's conflict and changes nothing. They give the order that works: after the user reviews each conflict, gbrain apply-migrations --force-retry 0.53.0 clears the wedge, then the command the inspect output names for that source (or gbrain apply-migrations --yes) settles it. That inspect command used to refuse a wedged version as not registered; it now works. Running a wedged migration by name, for example the accept command a conflict message names, still exits 2 but now says the version is wedged and names those steps, instead of calling it not registered. Nothing runs the migration again by itself, and the exit status of apply-migrations, post-upgrade and upgrade does not change." },
  { since: '0.60.733.0', id: 'commit_paths_unmerged', kind: 'fix', text: "gbrain git commit-push now refuses, before staging anything, when a file you name still has unresolved merge conflicts in the index, for example after a merge, rebase or stash pop that stopped on a conflict. It used to stage the file and commit it with its conflict markers as if it were resolved, and on an ordinary checkout push it. The refusal is commit_paths_unmerged (exit 1): nothing is staged or committed, the file stays unmerged, and the message names each file. Resolve each one with the user (edit out the markers, keeping the changes from both sides that belong in the file, since one side may be a write gbrain made), mark it resolved with git add -- <file>, then rerun the commit. The same check covers every gbrain write that commits named files, such as lint --fix and connector writes." },
  { since: '0.60.733.0', id: 'git_large_index_listing', kind: 'fix', text: "gbrain git commit-push no longer fails on a large checkout with git_unavailable \"git ls-files -v failed: exit -1\". Its git calls were limited to 1 MiB of output, so naming a folder whose index listing passed that (a few thousand tracked files with long names, more on a checkout of hundreds of thousands) killed git; they now read git's whole output. A git command that is stopped before it finishes (its time limit, or a signal such as the out-of-memory killer) now reports git_command_stopped with its reason (timeout or signal) instead of git_unavailable, still exit 1, and gbrain never uses its partial output as the answer. A push, fetch or remote listing stopped after the local commit still reports push_unconfirmed (exit 4)." },
  { since: '0.60.733.0', id: 'atom_retirement_keeps_tier_9456', kind: 'fix', text: "An atom a re-extraction retires now keeps the trust tier and write origin its extraction gave it, and an atom a later extraction produces again comes back at that tier. The retirement used to store the atom as unknown with no origin, so a revived atom stayed unknown. The same holds for every page a derived writer retires (chronicle events, synthesis outputs, gbrain repair stale-atoms). Atoms retired before this release keep the tier they were stored with." },
  { since: '0.60.733.0', id: 'provider_response_unparseable_9466', kind: 'fix', text: "A model provider that answers with a success status and a body that is not one JSON document (a route that streams when a request omits stream is the common cause) now fails with the non-retryable code provider_response_unparseable instead of a transient error. A facts job that hits it ends on its first attempt instead of retrying the same paid call, gbrain facts retry-dead does not resubmit it, and its recorded error reads cause=AIConfigError provider_response_unparseable. No response text is kept. Fix the route, for example with gbrain config set provider_chat_options.<provider>:<model> '{\"stream\": false}', then retry the job." },
  { since: '0.60.733.0', id: 'sync_freshness_content_directory_9471', kind: 'fix', text: "gbrain doctor's sync_freshness no longer fails a source whose folder sits inside gbrain's own content directory (for example one added beside the default source with gbrain sources add) and no longer tells you to run gbrain sync for it, a command that refuses such a source with sync_not_applicable. It counts the source as a content directory where sync does not apply and names gbrain import <dir> --source <id> for adding files instead." },
  { since: '0.60.734.0', id: 'repair_write_gate_markers_9511', kind: 'breaking', text: "Managed file repairs (gbrain repair rows-behind, file-drift, frontmatter, slug-conflicts, fence repair and local-edit adoption) now run the write gate a sync of the same file runs, with the file's path, so they keep a page's instruction_like flag or quarantine instead of stripping it, and an owner allow rule scoped to that path holds during the repair. Under write_gate.external_mode=reject, a repair of external instruction-like content now refuses with write_gate_rejected, the way sync already holds that file, instead of publishing it. If a repair refuses this way and you trust the file, allow it with gbrain trust allow --source <id> --uri-prefix <path>, or edit the file, then preview and apply the repair again; nothing was written." },
  { since: '0.60.734.0', id: 'relink_keeps_fact_instant_9260', kind: 'fix', text: "gbrain facts relink no longer changes a linked fact's trust tier or write origin, and no longer rounds its valid_from and valid_until to the second; the entity page's facts table keeps the stored instant to the millisecond. A fact whose stored instant is finer than a millisecond (only raw SQL or a database clock default writes one) is now left unlinked and counted claim_unfenceable instead of being linked with rounded dates. Facts linked before this release keep the dates they have." },
  { since: '0.60.734.0', id: 'consolidate_restatement_stays_open', kind: 'fix', text: "The consolidate upkeep step now ends a fact only at the next fact in its cluster that says something else, by claim text and typed value. A value restated on a later date stays active from the date it was first stated, and every restated copy ends together when the value changes. Before, each copy ended at the next copy's date, so the date a value was first stated was no longer on any active row. Facts consolidated before this release keep the dates they have." },
  { since: '0.60.734.0', id: 'open_facts_repair_8194', kind: 'add', text: "New command: gbrain repair open-facts opens facts that were saved private before facts.default_visibility became world, so remote callers that are not the brain owner can recall them. Nothing changes until the operator runs it on the brain host: preview with gbrain repair open-facts --source <id> --created-before <ISO-8601>, then apply exactly that preview with --apply --expect <hash>. Facts on private, member or quarantined pages, withdrawn, contested, expired or superseded facts stay private and are counted by reason. Each change is recorded in ~/.gbrain/repair/open-facts/, and --undo <ledger> makes the opened facts private again (what was already read stays read)." },
  { since: '0.60.734.0', id: 'remember_restated_private_hold_2875', kind: 'fix', text: "A remote remember of the exact claim of a private fact on the same entity that is more trusted than the caller is now stored private with a trust proposal, instead of as a world copy other connected clients could read. The operator lists it with gbrain trust review and makes it world with gbrain trust confirm tp<N>. Other remembers are unchanged." },
  { since: '0.60.734.0', id: 'setup_turn_hook_unmarked_9505', kind: 'fix', text: "gbrain setup claude-code no longer exits 1 with turn_hook_not_loaded on a re-run, and doctor's harness_wiring no longer warns that the per-turn hook is missing, when Claude Code has rewritten ~/.claude/settings.json and dropped the _gbrain key from gbrain's hook entries. The check now recognises a hook entry that gbrain setup wrote (its setup receipt owns the entry) with or without that key. Nothing to do after upgrading; if you saw the warning, your hook was already working." },
  { since: '0.60.734.0', id: 'git_reconcile_stopped_retryable', kind: 'fix', text: "gbrain sources git-reconcile now reports a source whose commit-push stopped with git_command_stopped because a git command ran past its time limit or was killed from outside as failed and retryable, exit 4, instead of needs_user, exit 1. A script that retries on exit 4 now retries it. A git command stopped by its output limit, or one that crashed (SIGSEGV, SIGBUS, SIGILL, SIGFPE or SIGABRT), still reports needs_user, exit 1, because a retry stops the same way." },
  { since: '0.60.734.0', id: 'frontmatter_validate_every_path', kind: 'fix', text: "gbrain frontmatter validate now checks every path it is given. With several paths it used to check only the last one, so a bad file named earlier could pass with exit 0. It now checks all of them, exits 1 if any fails, and refuses before checking anything when a path does not exist. With --json and more than one path, the output adds a targets list." },
  { since: '0.60.734.0', id: 'serve_http_refused_not_activity_9484', kind: 'fix', text: "gbrain serve --http no longer counts a request refused for a missing or wrong bearer token as activity. Idle upkeep waits for a quiet interval, and requests anyone could send without a token used to reset that interval, so upkeep might never run. Authenticated requests, including pings, still count as before." },
  { since: '0.60.734.0', id: 'update_cache_future_stamp_8795', kind: 'fix', text: "The update check no longer trusts a saved answer stamped in the future. After a computer's clock moved backwards, the saved answer could stay \"fresh\" and block every refresh, which hid newer releases and a withdrawn-release notice. A saved answer more than 5 minutes ahead of the clock is now stale and is replaced on the next check." },
  { since: '0.60.734.0', id: 'title_arm_candidate_cap_7082', kind: 'fix', text: "On a local search (the CLI and gbrain serve's local callers), the title step now ranks at most 5,000 of the pages that match the query in their title or timeline: the 5,000 with the lowest page ids, so the same pages on every call for the same data. Before, a very common word made it rank every matching page and read every matching timeline until the keyword time limit. A query that matches 5,000 pages or fewer gets the same result as before, timeline-only matches included. When the cut applies, the pages whose title holds the words come first (the rows remote callers get), then the other matching pages among the 5,000 kept, and hybrid search reports `keyword_candidates_incomplete`. A query of several words is cut on the pages that match the whole query, not word by word. Remote callers' results do not change." },
  { since: '0.60.734.0', id: 'guard_ledgers_fail_closed_7632', kind: 'fix', text: "On Postgres, a database write role that neither owns gbrain's purge and withdrawal ledgers (`fact_purges`, `fact_withdrawals`, `take_purges`, `page_purges`, `page_segment_derivation_purges`, `page_segment_derivation_purge_pages`) nor bypasses row-level security, and holds no policy that lets it read one, now gets a refusal on the writes that ledger's guard checks, where before the guard read the ledger as empty and let the write through: a purged claim, take, page or derivation could be stored again and a withdrawn fact saved active. The refusal is `writer_coordinator_required: writer state is unreadable to this database role` (P0001, `unreadable_state`); its hint names the table and the policy to add, and docs/ENGINES.md (\"Purge and withdrawal guards\") lists the policies a scoped write role needs. The guards stay SECURITY INVOKER: no trigger runs with different rights. The owner, a role that bypasses RLS, a ledger without row-level security and PGLite are unaffected. Where the role running migrations does not own a guard function, the upgrade leaves that function, names it on stderr and finishes; the next migration run by a role that owns it fixes it (#7632, #7659)." },
  { since: '0.60.734.0', id: 'purged_change_reason_8635', kind: 'fix', text: "A sync that read a page's change reason from a gbrain-reason commit trailer, then saved the page after a fact purge removed that text, used to store the purged text in the page's history as the reason for the change. The save now checks for the purge when it writes the history row and stores no reason instead; the page content still imports, and other files' reasons from the same commit are kept. Nothing to do. Reasons already stored before this release are not changed." },
  { since: '0.60.734.0', id: 'mirror_compare_reads_file_gst2843', kind: 'fix', text: "On a read-only mirror source, gbrain repair file-drift --held without --prefer now compares each held page with its file. A page that differs from its file reads prefer_file or needs_human with its evidence (what differs and which side is newer), and one that matches reads release_hold. Only a page whose file is gone reads no_drift with database_only. Before, every held page on a mirror read no_drift with database_only, whether or not it matched its file. Every compared page in details.pages now carries an evidence field, null when nothing was read. The comparison still writes nothing, and sync holds the same pages as before." },
  { since: '0.60.734.0', id: 'held_compare_complete_window_gst2843', kind: 'fix', text: "A gbrain repair file-drift --held dry run (a comparison, or a --prefer preview) now reports complete: false while held pages remain past its window, and details.window.next_command names the command for the next window. Before, complete was true after every window, even with thousands of held pages left. Applies keep the old meaning: every item of the approved window was attempted." },
  { since: '0.60.734.0', id: 'hold_by_code_counts_all_gst2843', kind: 'fix', text: "gbrain sources status --json now counts git_holds.by_code over every hold of the source. Before, the counts came only from the held files the listing read (at most 500), so a source with more holds under-counted each code. A code with no held file in the listing has no example. If the per-code count cannot be read, by_code falls back to the listed files and by_code_complete is false." },
  { since: '0.60.734.0', id: 'fact_rows_observed_date_gbra574', kind: 'fix', text: "Saved facts in query results now say when they were said. The facts block (on by default for a query with a token budget), the temporal fact reserve, the facts arm and recall's date headers fill the observed date in their [observed ...; valid ...] header from the page the fact was taken from, read under the caller's own page access, so a page the caller may not read dates nothing. If that read fails the header shows observed unknown and the response reports the degraded stage fact_observed_date_unavailable (recall: facts_degraded reason fact_observed_date_unavailable). Copies of one claim take one row in the facts block, dated as first stated and followed by (stated N times, last DATE); facts that differ by even one word keep their own rows. Question ranking of saved facts now matches words on their stems, with a word matched only through its stem ranking a little below an exact match (a question naming Roger puts a Roger fact above a Rogers fact), and dates, years and auxiliary verbs such as had or been no longer count toward the match, so a question phrased as of a date admits the facts it names and a fact sharing only a year with the question is no longer admitted. A fact about another person who shares the named person's surname can still be admitted when it also shares a verb with the question; its row names that person." },
  { since: '0.60.734.0', id: 'superseded_fact_valid_until_gbra574', kind: 'fix', text: "When a newer fact replaces an older one, every writer now ends the older fact's validity by one rule. It ends on the newer fact's valid_from when that date falls after the older fact began and before the older fact's own end (or now, if it had none); otherwise it ends at its own earlier end or now, and never before its own valid_from (a fact dated in the future ends where it begins). Per writer: remember with replaces (managed or not) and the engine supersede path used to leave the older fact open-ended when the newer fact was backdated, and now end it at the time of the write; the unmanaged remember that strikes the row in a page's facts table used to end it on today's date and now ends it at the newer fact's valid_from, which for remember is the time of the write; an accepted gbrain decide proposal used to end it at the time of acceptance and now ends it on the newer fact's valid_from when that falls inside the older fact's window; expireFact takes an optional successor date and applies the same rule. Extraction already used the rule and only gains the backdated case. A backdated replacement is one dated on or before the day the older fact began. For one of those, the older fact's end date is the day gbrain learned of the replacement (the time of the write), not a date taken from the source, unless the older fact already had an earlier end, which it keeps. Only future writes change. No stored row is rewritten, and forgetting or withdrawing a fact works exactly as before." },
  { since: '0.60.735.0', id: 'archive_rescope_on_shared_9563', kind: 'fix', text: "Conversation archive pages written while a brain was personal are now kept to the owner as soon as a command makes the brain shared: gbrain access member add and member enable (before the new member is added, enabled or bound to a token, so its credentials never read those pages), gbrain config set brain.audience shared and gbrain access owner set. Each prints one line on stderr per archive source saying the pages are kept to the owner or why they still wait. If the re-scope fails, member add and member enable change nothing and exit non-zero. Before, every member could read those pages until the next archive run." },
  { since: '0.60.735.0', id: 'forward_fyi_no_loop_gst2899', kind: 'fix', text: "A forwarded email whose own note asks nothing (\"FYI, see below.\") no longer opens a waiting-on-them loop just because the forwarded message contains a question. Since #8941 a forward keeps its whole body, and the loop detector read a question mark anywhere in it as your ask; it now reads only the note above the forward separator (Gmail's \"Forwarded message\" line or Apple Mail's \"Begin forwarded message:\"). The same rule applies to mail sent to you, so your \"Thanks!\" to someone's FYI forward counts as the reply again. A forward whose note does ask (\"Can you take this one?\") still opens a loop, and forwards still keep their full content in the brain. A loop that opened this way before the upgrade stays open until the other person replies or you close it yourself with gbrain loops drop <id> (gbrain waiting lists it)." },
  { since: '0.60.735.0', id: 'title_retry_reads_timelines_gst2899', kind: 'fix', text: "Keyword search finds the people behind a reworded relationship question again. When no page holds every word of a question, the title step retries with any word; since v0.60.338.0 (#7135) that retry read page titles only, so a question that names a company in words its people's pages don't use (\"Who is on the payroll at Acme?\") lost the people whose timeline names the company. For a local caller the retry now reads titles and timelines while at most 5,000 pages match the question's words, and titles only past that, so a date or a very common word in a question still doesn't pull every dated timeline into ranking. Remote MCP callers still match titles only. Results for such questions can change order, and on a very large brain the retry adds one bounded statement (0.03 to 0.14 s measured at 1,000,000 pages)." },
  { since: '0.60.735.0', id: 'open_facts_lapsed_timeline_8194', kind: 'fix', text: "gbrain repair open-facts now leaves a fact private when its valid_until date has passed, and counts it as lapsed in the preview. It also opens a fenced fact whose ## Facts table sits below the timeline sentinel; before, such a fact was always reported fact_left_private. The preview now warns that a fact saved private on purpose before the cut looks the same as a legacy one, and that --ids-file narrows the set." },
  { since: '0.60.735.0', id: 'date_only_since_utc_9533', kind: 'fix', text: "A date-only since now starts at UTC midnight on search, query and image query, the way a date-only until already ends at UTC midnight. A brain whose database timezone isn't UTC can gain or lose rows dated within that offset of midnight. On a UTC database nothing changes, and a since given as a timestamp or a relative duration is read as before." },
  { since: '0.60.735.0', id: 'connectors_sync_managed_brain_9124', kind: 'fix', text: "gbrain connectors sync <provider> run in the foreground now imports chat history on a brain whose writes go through the writer: it submits each imported page through the CLI's own write context, the way gbrain transcripts ingest already does. Before, the import was refused on such a brain and no conversations landed. If you saw that refusal, run gbrain connectors sync again in the foreground. A --background or scheduled sync and the connector_sync operation are unchanged and still refused there." },
  { since: '0.60.735.0', id: 'gmail_html_plain_body_8937', kind: 'fix', text: "A Gmail message part labelled text/plain whose content is really an HTML document (it starts with a doctype, html or head tag) is now stripped to readable text, the way an HTML part is. Before, the page stored the raw tags and CSS as the message body. Pages already imported are not rewritten." },
  { since: '0.60.735.0', id: 'captured_facts_codex_sessions_9554', kind: 'fix', text: "gbrain repair captured-facts now recognises facts captured from Codex sessions: it reads the session ids from the rollout file names in the live and archived Codex session folders, so those facts count as not suspect instead of unclassifiable. The preview's counts change on brains that capture from Codex; nothing is deleted or changed by the classification itself." },
  { since: '0.60.735.0', id: 'doctor_only_engine_free_9527', kind: 'fix', text: "gbrain doctor --only <check> on a check that needs no database (for example skill_resolver) now reports \"No finding\" at info level when the check has nothing to say, with no connection row. Before, it warned that the database checks stopped early and pointed at a connection that was never tried. A connection that really failed still reports the stop and keeps its connection row." },
  { since: '0.60.735.0', id: 'private_facts_grant_8194', kind: 'add', text: "Access tokens and OAuth clients have a new private-facts grant, `none` for every existing and new token and client, so remote fact reads stay world-only until the brain host opts a connection in: `gbrain auth rescope --token <name> --private-facts granted-sources` (or `--client <id>`) means this key will read every private fact in the sources its grant lists, including facts saved private on purpose, without rewriting any fact. A source opens only when the grant lists it by id: a token with no source grant, a source federated before or after the grant was written and a request's `source_ids` never add one. A fact held on, provenanced from or about a private, `readable_by`, folder-ruled, quarantined or member page stays hidden, and so does a fact with no page to check (no holding page, or a transcript lane such as the conversation archive). `context_pack`, `delta`, writes and audience or attested reads stay world-only. `--private-facts none` turns it off on the next request. No MCP operation or admin HTTP route can set it. `gbrain auth list` and `gbrain auth clients` show it." },
  { since: '0.60.735.0', id: 'migration_wedge_notice_history', kind: 'fix', text: "Ordinary commands (remember, recall, config get and every command except apply-migrations, post-upgrade, upgrade, doctor, init and setup) no longer print a \"wedged\" migrations_pending notice, with a request to ask the user for a forced retry, for an upgrade migration that stopped three or more runs in a row once a newer migration has completed since. apply-migrations already treats such a wedge as history; since v0.60.725.0 the notice did not, so a brain with three old partial rows for v0.53.0 printed it on every call. A wedge with no newer migration past it still gets the notice. The v0.53.0 shared-skills migration's source conflicts stay visible where an operator looks: gbrain doctor (as a warning, when connected), gbrain apply-migrations --dry-run and --yes, and post-upgrade name each source in conflict with a code and its next step, read from the migration's read-only preview, and none of them advises --force-retry. A new code, shared_skills_unmanifested, marks a source whose skills/ folder holds skills with no skillpack.json declaring them: declare the ones to share in a skillpack.json at the source's root, or keep the source out of shared-skills adoption with gbrain sources shared-skills <id> off. Doctor stops warning once the preview finds no source in conflict. A named run of a wedged v0.53.0 still refuses, now with the read-only preview as its fix instead of a forced retry." },
  { since: '0.60.735.0', id: 'guard_ledger_checks_gst2885', kind: 'add', text: "New doctor check `guard_ledger_checks` (Postgres only). It fails when a purge or withdrawal guard still lacks its ledger check, which happens when another role owned the guard at the v318 upgrade. It names the owning role and the fix. A migration run now prints a `guards:` line when it cannot re-create a guard for a reason other than another role owning it, where it used to stay silent. PGLite and brains whose guards are current see no change." },
  { since: '0.60.735.0', id: 'purged_change_reasons_repair_gst2886', kind: 'add', text: "New command gbrain repair purged-change-reasons. If you purged a fact before upgrading, a page's history could still show a change reason quoting it (#8635). Run gbrain repair purged-change-reasons on the brain host to see how many such reasons this brain holds; nothing runs it for you. If it finds any, the preview prints the apply command, which sets exactly those reasons to [purged] after you agree. Pages, files and Git history are not changed." },
  { since: '0.60.735.0', id: 'mirror_compare_names_writable_route_gst2869', kind: 'fix', text: "On a read-only mirror source, gbrain repair file-drift --held without --prefer no longer names a --prefer file (or --prefer database) preview for a page that differs from its file or a held deleted page whose file differs, in the page's why or in next_actions. Those previews read every mirror page as database-only and found nothing. The comparison keeps each page's verdict and evidence and says the page stays held until the user makes the source writable again with gbrain sources mirror-writable <id>." },
  { since: '0.60.735.0', id: 'rehold_retry_not_progress_gst2869', kind: 'fix', text: "A stopped sync pass no longer counts as progress when the only holds it rewrote were re-checked because gbrain sync unblock or gbrain sources retry-held asked and kept their code and file bytes (the hold is now marked retry_only; a retry that changed either restarts the hold and still counts once), or when the rewrite brought a transient hold (preparation_stalled, write_interrupted, or a page write that failed while frozen) to its attempt cap. Before, such a re-hold reset the abandoned-pass count once per retry round, so a source could stay pass_interrupted instead of reaching pass_abandoned." },
  { since: '0.60.735.0', id: 'sync_sigterm_recorded_gst2869', kind: 'fix', text: "gbrain sync stopped by SIGTERM or SIGHUP during a managed pass (an outer timeout, a supervisor stop, a closed terminal) now records the stop before it exits. The pass ends resumable with stop reason terminated, the drain stops terminated, gbrain sync status reads pass_terminated with the plain sync as its next step, and the run exits 143 (129 for SIGHUP). Before, the row was left open and status read pass_interrupted. A pass stopped this way that committed nothing still counts toward pass_abandoned, as a killed pass did. A second signal, or a run still saving or printing its result 3 seconds after the handler starts, exits as before. On PGLite the handler can start tens of seconds after the signal, as it already did before this change, so a supervisor that kills the process sooner leaves the pass open as before: it reads pass_interrupted and the plain sync resumes it. Ctrl-C and a sync job inside jobs work are unchanged." },
  { since: '0.60.735.0', id: 'facts_block_history_gbra574', kind: 'add', text: "When a query asks about the past, the facts block now shows the named person's or company's earlier values too. A question with a history word (before, earlier, previously, first, used to, in order and similar) or a date that has already passed, about one entity the brain has a page for, also pulls that entity's ended facts: facts a newer fact replaced, and facts whose valid_until has passed. Each keeps its own dates in its header, for example [observed 2025-01-16; valid 2025-01-16 to 2025-03-02], inside the block's usual share of the token budget, oldest first beside the current facts. A forgotten or withdrawn fact never appears, nor one from a page that was deleted and purged, and a remote caller sees only the world-visible facts it could already read. A question without such a cue gets exactly what it got before." },
  { since: '0.60.735.0', id: 'facts_block_told_after_gbra574', kind: 'add', text: "When a query names one date, each fact row in the facts block now says whether it was told after that date. A fact said after the date ends its header with \"; told after DATE\", for example [observed 2025-06-30; valid 2025-02-15 to unknown; told after 2025-04-01], and a fact whose saying date is unknown ends it with \"; learn date unknown\", so neither reads as known on that day. A question that names no date, or several, gets the headers it got before. Dates are read by the same fixed English grammar gbrain uses for time ranges in queries." },
  { since: '0.60.735.0', id: 'facts_block_contested_gbra574', kind: 'fix', text: "The query facts block now marks a fact another saved fact disputes, as recall already did. When a fact is in a pending gbrain decide supersede proposal, its row ends with (contested by #ID) naming the other fact, but only when the caller can read that other fact (remote callers see world facts only; private provenance and the trust floor apply). If the lookup fails, the rows carry no label and the response reports the degraded stage contested_unavailable." },
  { since: '0.60.735.0', id: 'conversation_fact_slot_windows_gbra574', kind: 'add', text: "Conversation facts can now carry a slot: where a person lives, who employs them or their role. `gbrain extract-conversation-facts` asks the model for it and stores it on the fact's ontology columns. The facts block in `query` then works out each value's validity window when it reads: an older value shows \"valid FROM to UNTIL\", ending where the next value starts, when both came from the same conversation page or the newer fact says the value changed in plain English (moved, joined, left, was promoted and similar); otherwise both values stay open and nothing is labelled. Nothing is closed in storage, so re-extracting pages in any order gives the same windows, a stored end date always wins, and a fact the caller cannot read never ends a window the caller can. Facts without a slot read exactly as before, and the ontology (ontology_get, ontology_propose, conflicts and the ontology-facts repair) ignores conversation facts. Pages extracted before this release keep their facts without slots and are not re-extracted automatically. To add slots to an existing brain, preview the paid run first with `gbrain extract-conversation-facts --force --dry-run`, which now prints the segment count and an estimated token count and dollar cost, then run `gbrain extract-conversation-facts --force`." },
  { since: '0.60.735.0', id: 'scan_allow_rule_entry', kind: 'add', text: "A .gbrain-scan-allow line of the form path:<glob> pattern:<rule> now allows only that secret-scan rule in the files the glob matches, so a rule that keeps flagging harmless values (for example jwt on newsletter unsubscribe links) can be quieted without turning off every other rule for those files. Existing fingerprint and path-glob lines work as before. A line that starts with pattern:, or with path: and contains a space, is read only as a rule entry: if it is malformed or names an unknown rule it allows nothing, and the push refusal, gbrain git scan and bootstrap verify name it. A bare path: line with no space is still a path glob, and gbrain git scan now warns about it." },
  { since: '0.60.735.0', id: 'takes_extract_dry_run_needs_yes_9547', kind: 'action', text: "`gbrain takes extract --from-pages --dry-run` without `--yes` no longer sends page content to the chat model. It lists the candidate pages and counts them, reports no claim count (`claims_extracted` is null and `dry_run` is true in `--json`), and writes nothing. A script that relied on a dry run classifying claims without `--yes` now needs `--dry-run --yes`, which classifies the candidates and still writes nothing." },
  { since: '0.60.735.0', id: 'auth_list_member_status_gbra593', kind: 'add', text: "gbrain auth list --json adds a member_status field to each token: enabled, disabled or removed for the member the token is bound to, missing when that member row is gone, and null for an unbound token. The status field keeps its meaning (active or revoked). The text table prints refused for an active token whose member is disabled or removed, because the brain refuses that token at verification (access_member_disabled)." },
  { since: '0.60.735.0', id: 'mirror_keep_deleted', kind: 'fix', text: "On a read-only mirror source, keeping the deletion of a page whose file the upstream edited after you deleted it now sticks. gbrain repair file-drift --held --side deleted --state tombstone_edited --prefer database lists such a page keep_deleted instead of removing a file gbrain never writes, and its apply (the user's yes on the preview hash) records the decision on the hold. The hold stays and is reported carried with reason mirror_keep_deleted, with needs_human false, in gbrain sources status, gbrain sync status and doctor, so it no longer asks again on every re-check; a re-check of the same file bytes keeps the decision. A new upstream edit of the file or gbrain restore of the page makes it ask again, and purging the deleted page moves the decision to the purged_differs hold. Nothing is deleted, restored or written into the mirror. Writable sources behave as before." },
  { since: '0.60.736.0', id: 'held_private_replies_2900', kind: 'fix', text: "A world restatement of a private fact that waits for the operator's accept is now also left out of think for remote callers who cannot read the private fact, and the reply to such a held write (remember, put_page and the other page writes, their outcome and write_request copies, get_write_request and list_write_requests) no longer carries contested.proposal_ref for those callers, so it reads like a saved write. The owner's callers, the local CLI and callers who can read the private fact still get the reference. A page write whose Facts row restates a more trusted private fact about the page's own entity kept on another page, or on none, is now held like a same-page restatement until gbrain trust confirm tp<N>; like the same-page hold, that includes the owner's own local writes and sync when the private copy is more trusted. A credential with a private_facts grant reads a held row again in get_page, search and think, as before the held-row page reads, when it can read every private copy that row restates. A remote get_page or get_versions of a page stored in segments now reports a size without the held rows." },
  { since: '0.60.736.0', id: 'held_row_page_reads_2891', kind: 'fix', text: "A world fence row restating a private fact that waits for the operator's accept (a remote put_page or remember restatement) is now left out of page, chunk, search and edit reads for remote callers who cannot read that private fact: get_page (as_of and known_as_of included), get_versions bodies and diffs, fetch, search, query, search_exact, get_chunks, the entity card and the edit_page diff. Such a caller's put_page keeps the held row it could not read, restored exactly as stored. The owner's callers, the local CLI and a member reading their own member page see the page as before. A world copy of the claim saved about another entity no longer lets a remote remember skip that hold. A held row also stays private when the page is synced or rewritten, until the operator accepts it with gbrain trust confirm tp<N>. If the lookup of held rows fails, the page read fails rather than return the page, and search drops every fence row. The page file in the brain repository still holds the world cell, and restatements that were never held stay world." },
  { since: '0.60.736.0', id: 'untrack_db_only_by_path_gst2964', kind: 'fix', text: "gbrain git commit-push --untrack in a managed canonical worktree now admits a file by its path under a storage.db_only folder that gbrain.yml declares and .gitignore ignores, whatever its extension. Before, every file was matched by its page slug, so .json, .yml and other files whose slug sync flattens refused untrack_not_db_only even though their folder was declared and ignored. A Markdown page still needs its slug under a declared folder. A code-extension file (sync's code list, .json and .yml included) is checked against the brain, because on a source whose sync strategy is code or auto it is a page with a flattened slug that a database-only folder does not cover: it is admitted only when no live page comes from it and the source's strategy does not import code, refused when it is a page whatever the strategy is now or when the strategy imports it, refused when the source's last finished sync has not seen it at its current version (run gbrain sync --source <id>, then rerun the untrack), and refused when the brain cannot be read within 10 seconds (retry when it is free). A tracked symlink out of the folder, a file reached through a symlinked folder and a sibling folder that only shares the name as a prefix now refuse. Each refusal's fix names what is missing for that file. The managed sync note about pages kept from the working tree now says that pages under a declared storage.db_only folder are database-only by declaration and need nothing, instead of telling every such page to be deleted or committed." },
  { since: '0.60.736.0', id: 'untrack_reads_brain_gst2964', kind: 'breaking', text: "In a managed checkout, gbrain git commit-push --untrack now reads the brain for every file, Markdown and CSV included, to learn which folder the source is rooted in (it used to read the checkout's top-level gbrain.yml, which refused every file of a source rooted in a folder and could admit a folder only that stray file declared, whose pages the next sync deleted), so on PGLite an untrack that worked while gbrain serve or a sync held the brain now refuses untrack_not_db_only and changes nothing until that process stops." },
  { since: '0.60.736.0', id: 'facts_block_retractions_gbra574', kind: 'add', text: "The query facts block now shows a later retraction next to the fact it answers, for every caller. When the block shows a fact about a person or company, a later fact about the same entity that retracts it or calls it off (retracted, scratch that, I was wrong, cancelled, called off, fell through, not happening, never happened, no longer planned, just a rumour and similar) comes right after it, with its own date header, inside the block's usual share of the token budget and row count. It pairs only when it is dated after the fact, its cue is not negated (\"not cancelled\", \"wasn't called off\" and \"isn't a rumour\" never pair), and it carries the same slot (the same dimension and value) or, leaving out the entity's name and the cue words, every word it has is in the fact or it shares at least two words with it. It is read under the caller's read policy, so a remote caller or another member never sees a retraction it could not already read, and a forgotten or withdrawn fact never appears. There is no setting; a question with no such later fact gets exactly the block it got before." },
  { since: '0.60.736.0', id: 'owner_remote_fact_reads_more_gst2951', kind: 'fix', text: "The brain owner's own remote agents (a credential bound to the member gbrain access owner set names, speaking for itself) now get the owner's private facts on the entity card (its recent facts and its active fact count) and the context_pack cards built from it, in the facts search and query attach about the entity a query names and the saved facts matching its words, in extraction_pending's list of facts saved without an entity, and in the similar facts forget names after a withdrawal. Before, these returned only world facts to every remote caller. Every other remote caller reads what it read before: another member, a labelled-only member, an unbound token, a call with no credential and the owner's credential speaking for an audience of several still get world facts only, and a private-facts grant admits a private fact on a world page where it already did. Page rules still apply to the owner, so a fact taken from a page whose readers leave the owner out stays hidden, and withdrawn facts stay out of every read." },
  { since: '0.60.736.0', id: 'owner_remote_fact_ops_gst2951', kind: 'fix', text: "The brain owner's own remote agents (a credential bound to the member gbrain access owner set names, speaking for itself) now read the owner's private facts through find_trajectory, ontology_get, ontology_conflicts and volunteer_chronicle, and get_write_attribution now finds a private fact for the owner's admin credential, as recall, query and think already did. Facts taken from a private page the owner can read come through too. Before, these operations returned only world facts to every remote caller, so a trajectory or ontology built from private facts came back empty for the owner. Every other remote caller reads no private fact it did not read before: another member, a labelled-only member, an unbound token, a call with no credential and the owner's credential speaking for an audience of several still get world facts only, and a private-facts grant still works on find_trajectory only. Page rules still apply to the owner, so a fact taken from a page whose readers leave the owner out stays hidden, withdrawn facts stay out of every read, and ontology from life/diary pages stays redacted for remote callers. Diary observations are now left out before each value resolves, so a newer diary note no longer hides the older value a remote caller may read." },
  { since: '0.60.736.0', id: 'dotdot_folder_names_inside', kind: 'fix', text: "Files in a folder whose name starts with two dots, such as ..drafts or ..., are now treated as inside the brain by the path checks this release fixes. Before, gbrain refused or skipped them, or called them outside, at those checks. Remote file uploads into such a folder are still refused; a separate fix covers that check. Three outputs change for such folders. First, gbrain frontmatter now expects the slug ..drafts/note for ..drafts/note.md (the same rule as any other folder) instead of note. Second, an extract-atoms transcript under meetings/..drafts/ gets the meetings label instead of corpus. Third, the LongMemEval call plan records a tracked, unchanged input under a ..inputs/ folder as a pinned INPUT line instead of a PRECONDITION. A gbrain.sourceRoot of ..drafts now scopes git commit-push to that folder instead of the whole checkout. Paths that really leave the brain are still refused." },
  { since: '0.60.737.0', id: 'conversation_extraction_no_slot_gbra574', kind: 'fix', text: "`gbrain extract-conversation-facts` no longer asks the model for a slot (where a person lives, who employs them or their role), because asking made it save fewer facts, wishes and preferences most of all. New conversation facts carry no slot, so skip the paid `--force` re-extraction the 0.60.735.0 notice suggested for adding slots: it now adds none. A fact stored with a slot under 0.60.735.0 keeps it, and its validity window, until the part of its page it came from is extracted again (an edit there, or `--force`, which re-extracts every page); the new rows then have no slot, and those facts read as they did before 0.60.735.0. The fact text is kept either way." },
  { since: '0.60.738.0', id: 'dedupe_preview_entity_duplicates', kind: 'add', text: "New: gbrain dedupe --preview lists groups of person and company pages that are likely the same person or company, with the evidence (the type of each shared key, never its value) and a class: clean, likely, weak, thin or conflict. A group is clean only when its pages share an account or registry id (a LinkedIn profile, a GitHub login or an id field the schema pack declares) and exactly the same name; a shared email, phone, X handle or company domain alone makes it likely. When two pages from different sources share no account or registry id and their LinkedIn profiles, GitHub logins or declared ids differ, the pair is a conflict for review, never a likely or weak match; correct the wrong id on one page if they are one person. Two such pages inside one source are listed as likely, with the differing id named in the evidence. Each shared email, phone, X handle or domain also shows how many other pages carry it, with the same name and with other names. --json prints a versioned contract, and --kind and --source narrow the list. gbrain doctor gains an entity_duplicates check that counts the groups and warns when there are any. Both only read: nothing is merged, linked or changed. A schema pack can now declare identity_keys on a page type, naming the frontmatter fields that hold one id per person or company." },
  { since: '0.60.738.0', id: 'mention_links_thin_pages_9675', kind: 'fix', text: "Mention links change on the next mention sweep. Text that writes @handle now links to the person whose frontmatter names that X handle. A page that is only titled with a name another page of the same kind claims as a frontmatter alias or handle stops collecting that name, and those mentions move to the claiming page. A one-word person page titled with another person's first name stops collecting bare mentions of that first name. No page is edited; only the mention links move." },
  { since: '0.60.738.0', id: 'dream_named_phase_no_database_9608', kind: 'fix', text: "gbrain dream --input <file>, or gbrain dream --phase <name>, run with no database connection used to exit 0 after the phase it was asked to run skipped. Now a phase you named, or that --input implies, that skips for want of a database ends the command with database_error and exit 1 (the error envelope under --json). Other named phases that need no database still run first, and their report is not printed when the refusal fires. A plain gbrain dream names no phase and still exits 0 when it can only run the filesystem phases. A script that runs dream with --input or --phase and checks the exit code now sees the failure; fix the database connection (gbrain doctor --json names the cause) and run it again." },
  { since: '0.60.738.0', id: 'dream_summary_keeps_earlier_runs_9598', kind: 'fix', text: "The dream summary page for a date now keeps the links a previous synthesize run wrote that day, as long as each linked page still exists, instead of keeping only the latest run's pages. \"Pages written\" still counts the latest run, and a new \"Pages from earlier runs today\" line counts the pages kept from earlier runs. The earlier runs' pages are read from the previous summary's list, which holds at most 20 links, so after a run that wrote more than 20 pages the kept count is a lower bound." },
  { since: '0.60.738.0', id: 'slack_missing_user_daily_relist_9601', kind: 'fix', text: "Slack sync now looks a user up again when the last users listing lacked them and that listing is more than a day old, instead of waiting up to seven days. A new member's name replaces their raw id on day pages written after the next sync. A Slack Connect user from another workspace never appears in the listing, so a workspace with shared channels may make one extra full users listing a day." },
  { since: '0.60.738.0', id: 'conversation_name_keys_gbra574', kind: 'default', text: "`gbrain extract-conversation-facts` now keeps a name tag on a fact about a person or company that has no page, instead of storing the fact with no entity (the 0.60.162.0 rule, which still applies to every other writer). The tag is the full name in slug form without a folder (Alice Example becomes alice-example); a single word such as a first name or a topic keeps no tag. No page is created, lists of pages never show a tag, and only new extractions get one. A page written later at that file name (people/alice-example) reads the tag's facts, and `gbrain facts relink --conversation --unbacked` (preview with --dry-run) moves them onto the page the name resolves to. Forgetting or purging a fact on a tag now applies to that claim across the whole source (a forget refuses with claim_linked while the same claim is active on another person's or company's fact), and a claim forgotten or purged for anyone never comes back on a tag; facts already stored on a bare slug with no page are treated the same way. Two people with the same full name in one source share a tag until a page or alias separates them (docs/guides/facts-relink.md). Turn tags off with `gbrain config set facts.unbacked_entity_keys false`." },
  { since: '0.60.738.0', id: 'conversation_slot_tagging_gbra574', kind: 'add', text: "`gbrain extract-conversation-facts` tags slots again (where a person lives, who employs them or their role), now with a second small call after extraction instead of in the extraction call itself, so the facts it saves are the same as without slots. The call reads only the facts the extraction produced about a person whose page it named exactly, at most 10 per conversation window, so a brain whose conversation facts name no person page makes no extra call. It is counted in the run's cost cap, the per-page cap and the `--dry-run` estimate. A window whose tagging call fails keeps its facts without slots, the run's summary counts it, and `--force` tags it again. Pages extracted before this release keep their facts without slots until that part of the page is extracted again; to tag them now, preview the paid run with `gbrain extract-conversation-facts --force --dry-run`, then run it with `--force`." },
  { since: '0.60.738.0', id: 'setup_names_owner_gbra585', kind: 'default', text: "gbrain setup <harness> --serves several (and gbrain access serves several --owner <id>) now names the brain owner when the brain has none: it adds a member from --owner <id>, or by default from your login name as a member id, and runs gbrain access owner set on it. The preview shows it first. An owner that is already set is kept, and no key or OAuth client is rebound: the receipt lists each live credential bound to no member with the gbrain auth rescope --token|--client <name> --member <owner> command that binds it. A script that ran setup --serves several on a brain with no owner now finds one more enabled member, the owner, in gbrain access member list. Pass --owner <id> to choose who it is." },
  { since: '0.60.738.0', id: 'auth_create_member_read_write_gbra585', kind: 'default', text: "gbrain auth create <name> --member <id> without --scopes now mints a key with read and write only. It used to mint the grandfathered full access, admin included, so a key handed to one person could call admin tools such as get_stats and see brain-wide counts. A script that runs gbrain auth create --member and then calls an admin tool with that key now gets insufficient_scope; pass --scopes read,write,admin to mint the old full access. An explicit --scopes still wins, a token made without --member keeps the old default, and tokens that already exist are not changed." },
  { since: '0.60.738.0', id: 'setup_member_keys_read_company_gbra585', kind: 'default', text: "gbrain setup <harness> --serves several and gbrain access serves several now mint each member key with a fixed source list instead of the default grant: it writes to the run's source and reads that source, the company source when it exists (gbrain setup --shape company), and every source federated when the key is minted. So members read the company pages and imported calls, including calls they did not attend, without federating company, which stays out of default search. A source federated later reaches these keys only when you run setup again (a re-run adds sources to such a key and never removes one); before, a member key read every federated source as soon as it was federated. A key for a named --source now also reads the federated sources and company. Keys minted before this release, and any key setup did not mint with a list, are not changed. The preview names the list and how many pages company holds." },
  { since: '0.60.738.0', id: 'setup_history_choice_gbra585', kind: 'action', text: "gbrain setup <harness> --serves several on a brain that serves one person and already holds pages no rule or readable_by restricts (a journal, DMs, chat, mail, the conversation archive) now refuses with setup_history_choice_required and writes nothing. The refusal names how many pages every member's key would read, how many are DMs, chat or mail and how many are in the conversation archive; it also refuses when it cannot count them. Run it again with --labelled-only to keep that history private (each member reads only pages labelled for them; on a brain with the company source, setup also adds one folder rule, company/ in source company, readable by the owner and the members, so they still read the company pages and calls, and a re-run adds new members to it, which waits for gbrain access apply because it widens the rule) or with --open-history to let every member read it, which is what setup did before without asking. A new brain, a brain with no such pages and a brain that already serves several people are not asked." },
  { since: '0.60.738.0', id: 'serves_labelled_only_needs_owner_gbra585', kind: 'action', text: "gbrain access serves several --labelled-only on a brain that has the company source and no owner now stops with a BLOCKED company/ line and writes nothing, where it used to label the members. The labelled-only run adds a folder rule company/ in source company so labelled-only members still read the company pages, and that rule's readers start with the brain owner. Run it again with --owner <member id> (the member is added when missing and named the owner), or name the owner first with gbrain access owner set <member> and run it unchanged." },
  { since: '0.60.738.0', id: 'member_share_about_member_held_gst2897', kind: 'default', text: "A member credential's remember with share: true about another enabled member (an entity under people/<member>/ or people/<member>) is now stored private, with a pending proposal the brain owner lists with gbrain trust review and shares with gbrain trust confirm tp<N>, instead of being shared with every reader of the source at once. The reply says visibility \"private\" and carries a held field naming the proposal and the member. A share about the team's work, about the caller itself, or by the owner's own credential is unchanged. The member a shared fact is about can now withdraw it with forget, where only the brain host could before; it still cannot withdraw a shared fact about anyone else. A member's visibility \"world\" about another member is refused as before, and the refusal no longer tells the agent to retry with share: true." },
  { since: '0.60.738.0', id: 'calls_kept_to_attendees_gst2904', kind: 'default', text: "gbrain import --calls on a brain that serves two or more people (two or more enabled person members, and config access.serves is not one) now keeps each new call to the brain owner plus the teammates its Attendees or Participants line names, matched exactly by email, member id or a display name only one person holds. A teammate who was not on a call gets not_found for it. A call with no attendee list goes to the owner only, and names that match nobody are listed in the import output, never guessed. The import stays open as before, with the calls_not_scoped notice and the command to run, when no owner is named, the owner is not enabled, or any connection bound to no person still reads the brain, so the owner's own assistants never lose a call. Pass --readers source to import open as before. Calls imported earlier are not changed. A one-person brain, including one whose assistant sits in group chats, imports exactly as before." },
  { since: '0.60.738.0', id: 'setup_ties_owner_gst2904', kind: 'default', text: "gbrain setup claude-code|codex --serves several --members <ids> --shape company (or both) now writes serve --stdio-member <owner> into the harness entry it installs when no member is named for it, so that assistant reads as the brain owner and imported calls can be kept to the people on them. The owner is the one the brain already has, else the one this run names (--owner, default your login name). Setup says so in a note and in the mcp step. It never ties an entry that already names a member, an entry a plugin serves, or one on a host where OpenClaw or Hermes is installed. With --transcripts, setup now prints one line per imported call with its readers, and the names it could not match with the command that adds a reader. Pass --no-stdio-member to leave the entry unbound as before; imported calls then stay open to the company source's readers, with the calls_not_scoped notice." },
  { since: '0.60.738.0', id: 'orphaned_refresh_reclaim_9649', kind: 'fix', text: "A gbrain sources refresh whose process is gone and whose row has stayed in syncing for a whole refresh sync budget (sources.refresh_sync_budget_ms, 5 minutes by default) is now completed by the owner on its own, the way a refresh whose budget runs out completes with members still behind. Writes to its sources stop being refused with worktree_refreshing, the row records completed_by owner_reclaim and lists the lagging sources in sync_deferred, and each of those catches up on its next sync. Before, such a row refused every write to the checkout until someone ran gbrain sources refresh. A refresh whose process is still running is never touched." },
  { since: '0.60.738.0', id: 'mirror_holds_whole_class_apply', kind: 'add', text: "gbrain repair file-drift --held --side unknown|database|both --prefer file --whole-class --apply --expect <hash> --yes applies a complete whole-class manifest after the user agrees to its hash: each page is re-read and applied only while its pins still match, on a read-only mirror the file is imported into the page database-only (a page version and a private backup first, the checkout untouched), and a stopped apply prints its resume command first and exits 1. A reconcile approved with keep_file_bytes on a source that is a read-only mirror now imports database-only when the file still matches the approved bytes, instead of refusing source_changed." },
  { since: '0.60.738.0', id: 'mirror_holds_whole_class_preview', kind: 'add', text: "gbrain repair file-drift --held --side unknown|database|both --prefer file --whole-class previews every held file-drift page of one side as one class: one manifest under the gbrain config directory and one hash, with the lines each page would lose, the pages kept held (kept_newer_page, and kept_protected_parts on a read-only mirror) and the data-loss card. On a read-only mirror the held window previews now list a page whose file is newer prefer_file instead of no_drift, and the held comparison names the whole-class preview instead of gbrain sources mirror-writable. A held deleted page whose file differs names neither preview: a tombstone_edited page names the keep-the-deletion preview (--held --side deleted --state tombstone_edited --prefer database) first and gbrain sources mirror-writable second, and a purged_differs page names only mirror-writable. The preview writes nothing else; --whole-class --apply refuses for now." },
  { since: '0.60.738.0', id: 'push_credential_refused_gst2961', kind: 'fix', text: "gbrain git commit-push (and the post-commit hook, scripts/brain-commit-push.sh and autopilot's git reconcile, which run it) now stops at once when the Git host refuses a push with \"Repository not found\" (HTTP 404, what a host tells an account that cannot see a private repository) or HTTP 403: it exits 1 with the new code push_credential_refused, class host_only, not retryable, instead of exit 4 with push_unconfirmed, which every caller read as \"try again later\" while commits stayed on this machine. The message names the credential helpers git asked, in the order it asked them, with the scope (system, global, local) and config file of each, which one answered and the account login it gave; it never prints or stores the secret. Until a push lands, doctor git_convergence warns about that checkout at once instead of after six hours, and put_page's lastPushStatus reads needs_attention. A script that branched on exit 4 to retry now sees exit 1 for this case: relay the message to the user, who makes git use a credential for an account that can push there, then run gbrain git commit-push --push-only. A dropped connection or any other failure keeps push_unconfirmed and exit 4, with the same retries as before. The same refusal over SSH (\"ERROR: Repository not found.\", \"ERROR: Permission to ... denied\") is classified too; there git asks no credential helper, so the message says the key ssh offers decides the account. A managed worktree's own Git-effect pushes keep their current retry." },
  { since: '0.60.739.0', id: 'recall_read_shared_merge_gst2898', kind: 'add', text: "recall on a key with the read-shared switch on and a private write source now returns both sets of facts when an entity's facts sit in that write source and in one shared source, each fact labelled with its source_id, and names the pair in merged_sources; it used to return no facts and ambiguous_entity. Every other split between same-named entities in two sources keeps that answer: keys without the switch, keys writing into a shared source, a namesake in a guest source, and two shared namesakes." },
  { since: '0.60.739.0', id: 'key_read_shared_gst2898', kind: 'add', text: "A key can now also read every shared source, now and later, while it writes to one: gbrain auth create <name> --sources <write-source> --read-shared on, or gbrain auth rescope --token <name> --read-shared on (--client <id> for an OAuth client; auth register-client takes --read-shared too). Shared means default plus every federated source, never a guest source and, for a key bound to a member, never another member's own source; a source federated later is read on the next call with no re-grant. Writes stay in the write source, and a write naming another source now says which source the key reads and the one it writes. Every existing key reads exactly what it read before: the switch is off until you turn it on, and a narrowing rescope lists the sources the key stops reading. gbrain sources federate now names the keys that read the newly shared source and those that do not." },
  { since: '0.60.739.0', id: 'secret_store_gst2988', kind: 'add', text: "`gbrain repair secret-spans --apply` now keeps each original it redacts in an encrypted secret store in the brain's database, and the marker it writes names the entry (<REDACTED:rule:ss_...>). Retained page versions of a redacted page are redacted too. The key is a file in ~/.gbrain/secret-store/keys/ (mode 0600, created on first use, never overwritten; GBRAIN_SECRET_STORE_KEY overrides it). New commands: `gbrain secrets list`, `gbrain secrets reveal`, `gbrain secrets restore` (preview, then --expect, for a false positive) and `gbrain secrets key status|export|import` (back up the key with a passphrase). The MCP operation reveal_secret reaches a token only when the owner adds it by name with `gbrain auth rescope --refresh-operations --add reveal_secret`, and only for pages that token can read. Nothing changes on a brain that never runs the repair." },
  { since: '0.60.739.0', id: 'publish_redacts_secrets_gst2988', kind: 'default', text: "A push of a brain checkout no longer stops when the commits it is about to push hold a value that looks like a secret. gbrain now rebuilds those unpushed commits with secret store markers (<REDACTED:rule:ss_...>), keeps each original in the encrypted secret store, keeps the old commits on this machine for 7 days under refs/gbrain/backup/, and pushes. Commits a remote already has are never rewritten, and files the scan cannot vouch for, or changes to .gbrain-scan-allow or .gitattributes, stay on this machine in one held commit. Pushes held by the old refusal are retried by the next maintenance pass; the upgrade itself writes nothing. To keep the old refusal, run gbrain config set secrets.on_push refuse or set GBRAIN_SECRETS_ON_PUSH=refuse." },
  { since: '0.60.740.0', id: 'agent_job_surface_confined_9669', kind: 'fix', text: "An agent job submitted with `submit_agent` now runs its tools on the tool surface of the connection that submitted it. A starter client's job can no longer pass a parameter or call a tool that the starter surface leaves out: a hidden parameter is refused with `param_not_on_surface` (the same reviewed exceptions as direct calls apply), and a hidden tool with `unknown_tool`. The refused tool call fails, and the job sees why. Jobs from full-surface clients and local jobs are unchanged, and jobs already queued at upgrade keep the full surface until they finish. `request_tools {tools}` on starter now lists only the parameters starter may pass, and the `list_pages` next-page fix keeps `slug_prefix`, `where` and `source_ids`." },
  { since: '0.60.740.0', id: 'starter_hidden_params_refused_9669', kind: 'fix', text: "A remote MCP caller on the starter surface can no longer pass a parameter that its tool list leaves out in a direct tool call. Before, the server accepted any of them, so a read-only client pinned to starter could pass `include_deleted: true` to `get_page` or `list_pages` and read soft-deleted pages, and `page_not_found` told it to. Now such a call is refused with `param_not_on_surface` and nothing runs; its fix is `request_tools {\"surface\":\"full\"}` where the connection may widen itself (the owner's stdio session, an OAuth client the operator has not pinned), and otherwise asks the user. A short list of hidden parameters that gbrain's own clients and fixes send stays usable on starter (page windows on `get_page`, the shared-skill reads, the thin client's source binding, the connection check's `recall`, `remember` and `submit_agent` arguments, a delegating client's `submit_agent` `queue`, `model` and `allowed_slug_prefixes`, `list_pages` paging with `offset`), each with its reason in `STARTER_CALLABLE_PARAMS`. The tools an agent job runs (`submit_agent`) follow the same rule. Structured fixes never name a parameter the caller's surface refuses (`page_not_found` on starter offers a search); plain-text suggestions may still name one. The local CLI and full-surface callers are unchanged." },
  { since: '0.60.741.0', id: 'dedupe_confirmed_counts_once', kind: 'add', text: "You can now settle the duplicate groups `gbrain dedupe --preview` lists. `gbrain dedupe confirm <group-id>` records that the pages are one person or company and links them as one identity; `gbrain dedupe confirm --clean --expect <hash>` does that for every clean group in the list you read; `gbrain dedupe reject <group-id>` records that they are different people, so the pair is never proposed again, and undoes a confirm. When the default source has a repository each decision is a file in its .gbrain/identity/ folder, committed through gbrain git commit-push, and a database rebuilt from git keeps it; that file names each member's source and slug, so a decision about pages in several sources puts every member's source and slug in the default source's repository, and confirm and reject refuse a group with a page in an owner-only source, or a page outside the default source that not every reader of it may read, there. Otherwise the database keeps it. A confirmed group counts once: rank_entities folds the group's pages onto its main page, and enrichment tiering counts the mentions in every source of the group. Groups linked by hand with entity_identity_link count as before, and get_links and get_backlinks still join identity groups only with entity_identity.union on. entity_identity_link and entity_identity_unlink now refuse to move or remove a page that gbrain dedupe confirm linked (identity_link_owned_by_dedupe); gbrain dedupe reject does it and records why. Nothing is linked without your confirm, and no page is merged, renamed or deleted." },
  { since: '0.60.741.0', id: 'owner_remote_reads_protected_gst3058', kind: 'default', text: "A credential bound to the brain owner, making a direct remote MCP call for itself with no room declared, now reads what the local CLI reads: get_page and fetch give it the private and held rows of a page's Facts fence, graph hops give it the stored edge context, and when the credential has no takes holders list of its own every read that filters takes by holder reads every holder (among them get_page and fetch, takes_list, takes_search, takes_scorecard, takes_calibration, search, query, recall, delta, think and synthesize). A credential with a list still reads only the holders it names, and synthesize now reads world takes only for a non-owner with no list. Every other context reads exactly as before: other credentials, stdio, on-behalf-of audiences, attested actors, agent jobs and group chats (a declared room). Known limit: agent jobs and group chats read as before this PR until GST-3066. An agent job now reads its client's stored takes holders list, else world takes as before. With a room declared, a get_page whole-body read or `view: 'markdown'` whose returned body carries rows a world-only read strips (private rows, held rows, takes) is marked not readable for the room (room_access reason private_label); the mark is per page, and it does not cover held rows inside read-view windows (lines, bytes, section, grep) or in a segmented page's markdown view, which an owner reads as on master. The local CLI's `--room` marks a page whose body carries private rows, held rows or takes private_label the same way. Known limit: editing or deleting a private Facts row through a remote put_page does not stick yet (the old row is restored); use the local CLI for that." },
  { since: '0.60.741.0', id: 'embedding_disabled_every_route_9715', kind: 'fix', text: "With embedding_disabled set in the config file or the brain's database, these routes no longer send page, fact, question or image text to the embedding provider (#9715): the synthesize phase-end embed, the safe-chunks, contextual-mode and secret-spans repairs, the doctor --remediate embed step, derived-writer, code and image imports, extract_facts fence facts, reindex-code, the grounding check and brainstorm now skip embedding, and gbrain embed (with its sync, connector and auto-fix callers) and gbrain reindex --multimodal refuse with the enable-command message when either plane disables embedding. Pages are stored without vectors and keyword search keeps working. Two cases still send until a later release. A contextual reindex (gbrain reindex --synopsis) queued before the setting was turned on sends its text when the worker runs it, and a gbrain reindex --multimodal that is already running finishes that run." },
  { since: '0.60.741.0', id: 'embedding_disabled_rechecks_9715', kind: 'fix', text: "With embedding_disabled set, a contextual reindex job queued before the setting was turned on now sends nothing when the worker runs it. One already running checks the setting again before each embedding send and before each per-chunk synopsis call, and a gbrain reindex --multimodal run already in progress stops before its next batch with the enable-command message (#9715). When the database setting cannot be read, the contextual reindex job, the doctor --remediate embed step and gbrain serve's background embed send nothing, keep the work pending and try again later, instead of counting it as done." },
  { since: '0.60.742.0', id: 'automatic_purge_keeps_rederive_concepts_9653', kind: 'fix', text: "The automatic purges (the cycle's purge phase, gbrain maintain and the purge job) no longer hard-delete a concept page that was hidden only because one of its input pages was purged and is still waiting to be rebuilt. Before, such a concept was removed about 72 hours after it was hidden, with its history and incoming links, and nothing rebuilt it (#9653). A concept a person or a sync deleted still expires on time, and gbrain pages purge-deleted --yes or gbrain delete --purge still removes a kept concept." },
  { since: '0.60.744.0', id: 'archived_source_token_reads_gst3163', kind: 'fix', text: "An archived source now reads as absent for every API token whose source list names it: get_page by slug, list_pages and every other page read stop returning its pages when the call names no source, as search already did, and gbrain sources restore brings them back for the same token. A token whose write source is archived, or whose every source is, reads nothing and answers unknown_source. gbrain access serves several and adding or enabling a member from the admin page now keep pages archived while the brain was personal to the owner before the member can read them." },
  { since: '0.60.744.0', id: 'refresh_link_backlog_after_lock_gst3107', kind: 'fix', text: "A managed gbrain sources refresh now holds the checkout's refresh lock only for its own import and the links of the pages it imported. The stale-link backlog that its member syncs used to derive under the lock (up to 1,000 pages per run) is now derived after the lock is released, with the same page cap and time budget. Other refreshes of the checkout stop failing with refresh_in_progress while that backlog drains. The --json result adds phase_ms, lock_held_ms and link_backlog." },
  { since: '0.60.744.0', id: 'secret_store_spooled_info_gst2988', kind: 'fix', text: "The secret_store_spooled notice a publish prints when it redacts is now an info notice that says what happened: every publish seals the originals in this machine's encrypted spool first, and the next owner push or maintenance pass moves them into the store (gbrain git commit-push does not). It used to be a degraded notice that said the store could not be written, which was not true. The secrets and secret-spans audit logs under ~/.gbrain/audit are now written at mode 0600, and an older file with looser permissions is tightened on its next write." },
  { since: '0.60.745.0', id: 'transcript_title_cap_9779', kind: 'fix', text: "A transcript import now gives a new page a title of at most 200 characters, cut with an ellipsis, instead of the whole title the harness reported, which for some harnesses is the session's opening text and could run to over 100 KB. Sessions already imported keep their titles, and the full text stays in the page body. Separately, page titles of any length can now be saved and upgraded: the exact-title lookup index is a hash index, so a brain holding titles over about 2,700 bytes no longer stops its upgrade and no longer refuses those page saves (#9779)." },
  { since: '0.60.747.0', id: 'owner_private_fact_edits_gst3064', kind: 'add', text: "A remote put_page from the brain owner's own credential that leaves out or rewords private fact rows now says so in its receipt: `private_rows_kept` gives the counts and a read-only `recall` lookup of the page's fact ids. The rows themselves are kept as before, because a remote put_page never deletes a private row or rewords its claim. To withdraw or replace a claim, `forget_fact` it and add a new row with a different statement. Other writers see no change." },
  { since: '0.60.747.0', id: 'owner_private_fact_reads_gst3064', kind: 'fix', text: "get_page `as_of` on an inline page now shows a credential bound to the brain owner, making a direct remote call for itself with no room declared, the page's private fact rows, as get_page and fetch already do. Every other caller, and `known_as_of`, reads as before. An owner's remote put_page still keeps stored private rows it leaves out, so delete or edit private rows with the local CLI for now." },
  { since: '0.60.747.0', id: 'label_edit_block_list_gbra593', kind: 'fix', text: "gbrain repair visibility --readers, and the new gbrain access member handover, now edit a readable_by written as a block list (one reader per line, the way put_page writes it) instead of refusing the page with label_edit_refused: the key line and its item lines are replaced by one flow-list line, and every other byte of the file is kept. A block scalar, a nested item or a duplicate key is still refused." },
  { since: '0.60.748.0', id: 'audience_counts_people_gst3180', kind: 'fix', text: "When no brain.audience is declared, gbrain now decides whether a brain is shared by counting the people behind its active MCP clients, not the clients. Clients bound to the same member count once, a client bound to nobody counts by itself, and the brain reads as shared at 2 members or 3 people. Two kinds of brain can change on upgrade. A brain that read as shared only because one member's three or more bound clients were active now reads as personal. A brain whose active clients are bound to two different members now reads as shared; before, it needed three clients. Clients bound to nobody count as before, so a brain whose three clients are all unbound still reads as shared until they are bound to their member (gbrain auth rescope --member) or brain.audience is declared. A brain with brain.audience set is unchanged. gbrain doctor shows the count in audience_reasons, and gbrain config set brain.audience personal|shared declares the answer." },
  { since: '0.60.748.0', id: 'gemini_default_3_5_flash_lite_9776', kind: 'default', text: "The gemini model alias, the Google provider's default chat and query-expansion model, and the Google judge on the eval takes-quality default panel now use gemini-3.5-flash-lite instead of gemini-2.5-flash, which Google retires on 2026-12-01 and already routes to gemini-3.5-flash-lite from that date. The price per token is the same. A config that says gemini, or that relies on the Google default, gets the new model after upgrading; one that names google:gemini-2.5-flash explicitly keeps it until Google switches it off, and gemini-2.5-flash-lite is still offered. Because gemini-3.5-flash-lite cannot switch its reasoning fully off, the takes-quality judge call to it is now capped and priced at the 32,000-token reasoning headroom, so an eval takes-quality --budget-usd that passed before can refuse earlier. Usage logged against gemini-2.5-flash still prices as before." },
  { since: '0.60.749.0', id: 'company_auto_link_gst3127', kind: 'add', text: "gbrain now links companies that are plainly one company across sources without asking: after each sync, cross-source company pages with exactly the same name that share a LinkedIn company page or their own site's domain, share an id no other page has, and name no different countries are linked as one identity (established_by dedupe:auto), which rankings and enrichment count once. Pages written by gbrain import, put_page or capture link at the next sync or reconcile. Run gbrain dedupe reconcile once to link the companies already in your brain. gbrain dedupe reject <identity> removes a wrong link and keeps that pair apart, even after a rename or a move to another source. People are never linked automatically, and no page is merged, renamed or deleted." },
  { since: '0.60.749.0', id: 'far_future_fact_rank_gst3170', kind: 'fix', text: "Newest-first fact reads now rank a fact whose valid_from is in the future by the time it was written, so a fact dated years ahead by mistake no longer stays at the top of entity facts, fact lists and question refresh. Facts dated today or earlier rank by their date as before." },
  { since: '0.60.749.0', id: 'extracted_deal_label_fundraise_gst3170', kind: 'fix', text: "Fundraising amounts the conversation fact extractor labels with a round or deal name (seed_round, series_a, round_size, deal_amount_usd and similar) are now stored under the fundraise metric, so one deal's amounts share one tag. Valuation, share price, cap, ownership, count, runway, loan, interest and target labels are never folded, and labels written in a page's Facts fence are kept as written. Facts already stored keep their labels." },
  { since: '0.60.749.0', id: 'remember_item_params_on_surface_gst3170', kind: 'fix', text: "A client on a narrower MCP tool surface, such as the starter surface, can no longer pass a remember parameter that its surface hides by putting it inside an items entry. Such a call is refused with param_not_on_surface, the same as the parameter at the top level. Full-surface clients and the local CLI are unchanged." },
  { since: '0.60.749.0', id: 'known_as_of_owner_history_gst3252', kind: 'fix', text: "get_page and get_versions with known_as_of now show a remote token bound to the brain owner the recorded history its current-time get_page shows: private editions of the page now at the slug, and the owner's view of a page's Facts fence. Before, every remote caller got only history recorded while the page was world-visible, so the owner's own agents read less than the owner. An edition whose own readable_by left the owner out stays hidden, and an earlier page that once held the slug keeps the world-only rule. Every other remote caller, another member or an unbound token, reads exactly what it read before." },
  { since: '0.60.749.0', id: 'owner_identity_command_gst3216', kind: 'add', text: "New command: gbrain identity shows who gbrain takes the brain's owner to be, worked out from what the brain already stores: the owner member's email, the account of each Google source the owner owns, and the owner's linked chat ids. A name never counts, and an identifier two members both claim counts for neither. It also names the page facts about the owner belong on. gbrain doctor gains an owner_identity check that warns when an identifier is shared between members, when several person pages carry an owner email, or when a Google source on a brain with several people is bound to no member. Nothing changes how facts are written yet." },
  { since: '0.60.749.0', id: 'page_writes_strip_nul_gst3170', kind: 'fix', text: "put_page, put_pages, edit_page and add_timeline_entry now save page text that holds a U+0000 character with that character removed, and keep every other character as written. Before, Postgres and PGLite refused the whole write with internal_error \"unsupported Unicode escape sequence\" and the page was not saved. A frontmatter value or key whose YAML escape reads as U+0000 is read without it too, and two keys that only U+0000 told apart are refused. An edit_page old_text holding U+0000 is refused with edit_no_match. append_page and capture still refuse text with U+0000." },
  { since: '0.60.749.0', id: 'imessage_pages_in_checkout_gst3022', kind: 'default', text: "On a personal brain whose default source is a Git checkout, iMessage chat-day pages are now also files under .gbrain-owned/<source-id>/ in that checkout: each sync that changed something makes one commit, and the files are pushed like your other pages (push-time redaction catches known key and token shapes only; one-time codes and passwords in message text are pushed as written, which is why the folder is used only with a remote proven private). Pages imported earlier stay in the database until their day changes or you run gbrain sync --source <id> --full. Shared, managed and repo-less brains, and checkouts that push to a repository gbrain cannot prove private, keep the pages in the database only. gbrain sources status <id> shows where they are; gbrain sources remove <id> takes the files out in one commit, and the remote's history still holds what was pushed." },
  { since: '0.60.750.0', id: 'slot_ends_every_reader_gst3170', kind: 'fix', text: "Recall, the entity card, hot memory, an entity's saved facts, search's saved-fact matches and the local gbrain recall command now treat a person's or company's slot value (an employer, a city, a role) as ended once a later value for the same slot is saved, the way the query facts block already did. Active reads drop the ended value and history reads show its end date. The end is worked out when the facts are read, from the facts that reader can see, so a fact a reader cannot see never ends one it can, and nothing is stored." },
  { since: '0.60.750.0', id: 'keep_quiet_private_gst3170', kind: 'fix', text: "Conversation fact extraction now saves a fact private when it restates a claim the speaker asked to keep quiet (\"keep this quiet for now, but ...\", \"off the record\", \"don't tell anyone\", or a sentence that opens with \"between us,\"), even on a page whose facts are otherwise shared. Other members' credentials and unbound tokens stop seeing those facts; the brain owner sees them as before. Facts extracted before this release keep their stored visibility, and a claim forgotten or purged earlier stays out. On a managed brain, a writer still on an older release saves such a fact at the page's visibility." },
  { since: '0.60.751.0', id: 'speaker_owner_marker_gst3216', kind: 'add', text: "Conversation pages imported from now on can carry a speaker_owner entry naming the speaker label whose turns are yours: interactive Claude Code and Codex sessions, your own ChatGPT and Claude exports, iMessages you sent and Gmail messages you sent. Agent-driven sessions, meeting transcripts and every other source stay speaker-unknown. gbrain honors the entry only when its own importer wrote the page, so an entry written or kept by an MCP caller is ignored. Pages imported earlier are not rewritten." },
  { since: '0.60.751.0', id: 'whois_phone_numbers_gst3256', kind: 'add', text: "gbrain whois (and the whois MCP tool) now looks up phone numbers: a query written only with digits, spaces and + - . ( ) / is compared with the phone and phones frontmatter of person pages in one canonical form (plus sign, country code, digits), so +1 555 555 0100, (555) 555-0100 and 555.555.0100 find the same person. A number without a country code is read with identity.phone_country_code (default 1). A partial number or the last digits never match. Such a query used to be tried only as a name and usually found nothing; email and name lookups are unchanged, and an email match still ranks first." },
  { since: '0.60.753.0', id: 'held_row_fact_reads_gst2979', kind: 'fix', text: "An API key granted private facts no longer reads a held fact row (a private restatement waiting on a visibility proposal) through recall, query, entity or the saved-facts match unless it can read every copy the proposals name, following a chain of held copies to its end. These reads now agree with get_page, which already hid such rows. The owner's own remote callers and the local CLI read what they read before." },
  { since: '0.60.754.0', id: 'apple_contacts_write_gst3278', kind: 'add', text: "New: gbrain apple-contacts write changes the owner's Apple Contacts through GBrain Helper on their Mac, one change per call, signed with an owner key and carrying the owner's own words as --owner-instruction. Nothing changes until you turn it on: apple_contacts.write is off by default (dry_run prints the request and sends nothing), the verbs that change or remove what is on a card (set, remove-value, group-remove, delete, merge) also need apple_contacts.destructive_writes on, which ships off, and the helper has its own switch, gbrain-apple-helper contacts-write on. Before the first change each day the helper saves a copy of every contact, journals each change, reads each card back, keeps daily limits (50 new cards, 25 deletes, 200 edits) and can put a whole batch back with gbrain-apple-helper contacts-restore --batch <id> --apply. gbrain apple-contacts status shows the switches. Syncing contacts into the brain is unchanged." },
  { since: '0.60.754.0', id: 'sync_unknown_drift_history_gst3328', kind: 'fix', text: "A managed sync now imports a Git edit to a page with no import record when the page still equals one of its file's three earlier committed versions, not only the file at the last synced commit, so a page that fell more than one commit behind its file (or whose last synced commit no longer resolves) is no longer held file_drift although only Git moved. A page edited in the database still matches none of them and stays held. Holds written before this release stay until re-screened: gbrain repair file-drift --source <id> --held (writes nothing) marks each held page that equals an earlier version of its file, and gbrain sources retry-held <id> followed by gbrain sync --source <id> --no-pull imports those pages and clears their holds. gbrain doctor's git_held_files advice for file-drift holds now names that preview instead of a per-page step." },
  { since: '0.60.754.0', id: 'migration_host_work_notice_quiet', kind: 'fix', text: "Ordinary commands (remember, recall, config get, stats and every command except serve, apply-migrations, post-upgrade, upgrade, doctor, init and setup) no longer print a migrations_pending notice on every call for an upgrade migration that is stopped on a source conflict a person has to settle (today only v0.53.0, the shared-skills content migration), even when no newer migration has run past it. That work waits on a person's decision, not on another run, so repeating it on every call changed nothing. gbrain doctor still warns about it with the read-only step that lists each source's conflict, gbrain apply-migrations and post-upgrade still report it, and gbrain serve still names it once at startup. A migration that has not run or only partly ran, and any other stopped migration, still gets the notice on every command, now also when the stopped v0.53.0 is there too: before, its message replaced theirs." },
  { since: '0.60.754.0', id: 'who_can_read_owner_only_sources', kind: 'fix', text: "gbrain access who-can-read and the open-page count (gbrain access serves, doctor open_shared_pages, the access serves several preview and the post-upgrade notice) now report the readers that get_page and search really serve on a brain that has, or once had, an owner-only source (an iMessage or Apple Contacts source, or a source marked owner_only). Before, once such a source existed, who-can-read said no member reads a page that a member does read (and suggested rewriting its readers), and the open-page count said every page names its readers. Reads themselves were always right. who-can-read now also lists only the owner for a page in, or derived from, an owner-only source, where it used to say every caller entitled to the source reads it." },
  { since: '0.60.754.0', id: 'sync_status_automatic_sync_gst3329', kind: 'fix', text: "gbrain sync status --json now has an automatic_sync field. enabled is false when the source has config.syncEnabled=false (gbrain sources set-sync <id> off): autopilot's per-source cycle, the freshness loop and gbrain sync --all skip it, and only an explicit gbrain sync --source <id> syncs it. Then why says so and fix previews gbrain sources set-sync <id> on --dry-run, which is the owner's call. The plain-text status prints an automatic sync: OFF line. State, reason and next are unchanged." },
  { since: '0.60.754.0', id: 'cycle_sync_off_skipped_gst3337', kind: 'fix', text: "gbrain dream and autopilot-cycle jobs now skip the sync phase of a source with config.syncEnabled=false (gbrain sources set-sync <id> off), reporting it as skipped with reason sync_disabled. Before, the cycle's sync phase synced it anyway, so gbrain dream --source <id> (the fix doctor's cycle_freshness check names) pulled and wrote a source whose sync was off, a Google source's paused contacts re-list included. Only an explicit gbrain sync --source <id> syncs such a source now. The cycle's other phases are unchanged." },
  { since: '0.60.754.0', id: 'cycle_freshness_sync_off_gst3337', kind: 'fix', text: "Doctor's cycle_freshness check now lists a source with config.syncEnabled=false as sync off (not checked) instead of reporting it as never cycled, stale or failing, and never names it in its gbrain dream --source <id> fix. A check whose only stale sources have sync off reads ok. Before, a never-cycled source with sync off counted as stale, so anything acting on cycle freshness could pick it and run a dream on it." },
  { since: '0.60.755.0', id: 'cli_inline_boolean_strict_9918', kind: 'breaking', text: "An inline boolean flag on a gbrain command now takes only true or false. A value such as --purge=0, --include-deleted=no, --dry-run=off or --json=1 is refused with invalid_params (exit 2) and nothing runs; before, any value other than false turned the flag on, so gbrain delete <slug> --purge=0 ran the irreversible hard delete instead of the recoverable soft delete. Write the flag on its own or --flag=true to turn it on, and --flag=false to turn it off. The bare flag and the space-separated form (--purge false) are unchanged." },
  { since: '0.60.755.0', id: 'repair_frontmatter_routes_holds_lc2', kind: 'fix', text: "gbrain repair frontmatter no longer brings back a deleted or purged page. Restoring such a page now always goes through the file-drift consent step (gbrain repair file-drift --held --side deleted, which previews the restore and asks the user first). A file held because its page was deleted or purged (file_drift, side deleted), two spellings of one path (page_identity_changed), an origin conflict or a write that raced the database is now listed needs_review with that hold's own fix, instead of safe: Import <path> as it is now. A file whose import would restore a soft-deleted page (page_deleted) or re-create a purged one (page_purged) is needs_review too. So are files whose paths differ only by case and name one page, held or not. Before, the repair's apply restored such pages without asking. A preview approved before this release is refused at apply for these files." },
  { since: '0.60.755.0', id: 'put_keeps_page_source', kind: 'breaking', text: "A gbrain put that names no source no longer writes a second copy of a page that lives in another source. Before, once the default source held one page, gbrain put people/alice-example --force for a page that lived only in your git source wrote a new copy into default. An unscoped get then showed that copy, while the page in the git source and its file kept the old text. Now that put is refused. The same check covers each page of gbrain put-pages (a refused page is reported in the receipt; the other pages are still written) and new pages begun or committed through begin_page_upload and commit_page_upload. The error names the source that holds the page and the command to run instead, for example gbrain put people/alice-example --source-id vault --force. Scripts that relied on the old behavior must now pass --source-id. A put that names or implies its source works as before: --source-id, --source, GBRAIN_SOURCE, a .gbrain-source file, or running the put from inside a source's checkout (a registered local_path), which writes to that source. commit_page_upload takes no source of its own, so a deliberate separate copy by upload names the source again with the global --source flag on the commit; running the commit from inside a source's checkout does not count as naming a source, because the commit writes to the source fixed when the upload began. When an unsourced put goes to default while your only other git source is federated, gbrain now prints the routing notice it already printed for other commands, and --quiet silences it." },
  { since: '0.60.756.0', id: 'purge_age_refused_9823', kind: 'breaking', text: "Purging deleted pages now refuses an age that is not a number, negative or infinite. gbrain pages purge-deleted --older-than, the purge job and the maintenance cycle stop with an invalid_argument error and delete nothing. Before, a negative age counted as 0 hours and permanently removed every soft-deleted page. Use 0 to purge every deleted page on purpose, or a positive number of hours." },
  { since: '0.60.757.0', id: 'setup_hermes_registers_mcp_gst2714', kind: 'add', text: "gbrain setup hermes now registers gbrain's MCP server in Hermes itself, by running Hermes's own hermes mcp add (answering its prompts with yes) and then hermes mcp test gbrain, where it used to print the registration step for you to run. Hermes writes the entry into its config.yaml. An mcp_servers.gbrain entry gbrain did not write, such as a hosted URL, is left as it is. With no hermes command on PATH or where Hermes's installer puts it, setup prints the command instead. An entry of gbrain's that carries other environment variables or settings is also left as it is, and a failed update puts the previous entry back and exits 1. gbrain setup hermes --instructions-only still leaves MCP alone, and gbrain setup hermes --remove now also runs hermes mcp remove gbrain." },
  { since: '0.60.757.0', id: 'dcr_connector_takes_widened_grant_gst3334', kind: 'fix', text: "Approving a self-registered connector (one that registered through the brain's open registration endpoint, such as claude.ai) now grants its whole current scope whenever its request names any scope it holds, so a connector you widened with gbrain auth rescope --client <id> --scopes read,write gets write the next time it connects and you approve it, even though it still asks for read. The approval page shows the scope you are granting. Its scope is still the ceiling, existing tokens and their refreshes keep the scope approved for them, and narrowing still applies at once. Clients you registered yourself keep getting only the scopes they ask for." },
  { since: '0.60.757.0', id: 'readers_key_misspelled_refused', kind: 'fix', text: "A page whose frontmatter names its readers with a key spelled any way but exactly `readable_by` (`Readable_By`, `readable-by`, `READABLE_BY`, `readable by`, `readableBy`) is no longer stored as a page every member can read. `put_page`, `edit_page` and `capture` refuse it with `readers_noncanonical` and write nothing, and `ingest_capture`, `brainstorm --save` and `sources reconcile` refuse it the same way. Git sync (classic and managed) and `gbrain import` hold such a file as `readers_noncanonical`: the rest of the source syncs and an existing page keeps its last imported version. A page that also carries the exact `readable_by` key is refused too, because it is not clear which spelling was meant. Write the key as `readable_by` (lowercase, with an underscore) on its own frontmatter line and save, sync or import again. Pages already stored with a misspelled key are not rewritten." },
  { since: '0.60.758.0', id: 'connector_job_deadline_9968', kind: 'fix', text: "A managed connector sync (Google, GitHub, Slack, meetings and the others) run as a sync job, with the job drain on (the default), now stops at the job's own deadline, less its reserve, instead of running until the job is killed at its timeout. The run ends partial (reason timeout), records its pending writes and counts, and saves the newest position whose writes have already committed, so the job completes and the next sync picks up from there; before, every such job ended aborted: timeout, used up its attempts and saved nothing it had not saved mid-run. A connector whose recorded last failure is recovery_required no longer shows as stopped once no request of the source still holds a recovery record. sources status and sync status show recovery_settled, and the next sync that ends without an error clears the record. A real retained publication still keeps the stop. The recovery_required refusal now names the request, its state and blocked_reason, and its fix is gbrain write-request -- <request id>; its wait for that publication never runs past the caller's deadline. gbrain sources writer status now also lists a request that has ended but still holds a recovery record. Nothing to run after upgrading." },
  { since: '0.60.762.0', id: 'plain_directory_db_edits_8079', kind: 'fix', text: "A managed sync of a plain-directory source (a folder with no Git checkout, added with gbrain sources add --path) no longer imports a file over a database edit of its page. When the page was last changed by a write that did not write its file (a put_page with sync.write_through off, for example) and the file differs from it, sync keeps the page, imports nothing for that file, reports it as a failed file (blocked_by_failures, code file_drift) and syncs the rest of the source. Before, an unchanged old file overwrote the database edit on every sync. To keep the database edit, update the file to match the page and sync again; to keep the file, import it explicitly with gbrain import <file> --source <id>. A file edit after a page write that also wrote the file (write-through on, or an import) syncs as before." },
  { since: '0.60.762.0', id: 'upgrade_restart_supervisors_8840', kind: 'add', text: "Self-upgrade restarts no longer leave a process dead or refuse because of another brain. An autopilot that nothing relaunches (the ephemeral-container start script runs it once at container boot, or it was started by hand) now starts itself again after a self-upgrade swap instead of exiting for good; under launchd, systemd, this brain's cron line or a declared autopilot_launcher it still exits for that supervisor. On macOS, gbrain upgrade reads each process's GBRAIN_HOME (else HOME) with ps -E, so another brain's serve on the same host no longer makes every restart refuse. A serve that gbrain's own serve service does not run now gets a refusal naming the exact command: systemctl --user restart <unit> for a systemd unit of your own (found from the serve's cgroup, any name), else the command line serve was started with. New key: gbrain config set self_upgrade.serve_launcher external lets every upgrade run that unit's restart command, or stop serve and wait up to 6 minutes for your own supervisor to start the new build; leave it unset and upgrades never restart that serve themselves." },
  { since: '0.60.762.0', id: 'dream_warns_no_job_worker_2772', kind: 'fix', text: "On a Postgres brain, gbrain dream now warns in its facts_drain line when no job worker is extracting facts: once a facts-absorb job has waited longer than GBRAIN_QUEUE_NO_WORKER_WARN_HOURS (default 1) on a queue where no job is running or has started in that time, the phase reports a warning that counts the waiting jobs, gives the oldest one's age and names the fix, gbrain jobs supervisor start. It used to report the phase as skipped, so a brain whose worker never started looked healthy while its facts stopped updating. The cycle still exits 0." },
  { since: '0.60.762.0', id: 'publish_strips_private_sections_10020', kind: 'breaking', text: "gbrain publish now removes a page's Timeline wherever it starts: at the first Timeline or History heading (any heading level, with or without a --- rule above it) or timeline marker, through the end of the page. It also removes gbrain's Facts and Takes blocks and every HTML comment, and anything after a block or comment that never closes. Before, the Timeline was removed only when a --- rule and one blank line came right before its heading, so most pages published it. A page whose frontmatter opens with --- and never closes is now refused with invalid_frontmatter instead of being published; close it with a --- line and publish again. A prose section headed History is dropped too, so read the output before sharing such a page." },
  { since: '0.60.763.0', id: 'dream_stored_caps_bind_gst3490', kind: 'fix', text: "Spending caps saved with gbrain config set now bind in five dream phases that ignored them. The calibration phases (cycle.propose_takes.budget_usd, cycle.grade_takes.budget_usd, cycle.calibration_profile.budget_usd) never read a saved cap and always ran under their defaults ($5, $3 and $0.50 per run). A saved 0 for cycle.extract_atoms.budget_usd, cycle.enrich_thin.max_cost_usd or max_total_cost_usd, or cycle.conversation_facts_backfill.max_cost_usd or max_total_cost_usd was read as unset, so those phases ran under their defaults ($0.30, $1 or $5); 0 now means spend nothing. If you saved one of these caps earlier, it applies on the next dream run; check it with gbrain config get <key>." },
  { since: '0.60.763.0', id: 'publish_frontmatter_fence_column_zero', kind: 'breaking', text: "gbrain publish now ends a page's frontmatter only at a --- line that starts at the beginning of the line, the same rule gbrain uses when it reads frontmatter. Before, an indented --- inside a multi-line frontmatter value (for example under notes: |) ended it early, and every frontmatter line after it was published. A page whose frontmatter is closed only by an indented --- is now refused with invalid_frontmatter instead of being published; close it with an unindented --- line and publish again. Republish any page whose frontmatter holds an indented --- line if you shared it before this release." },
  { since: '0.60.763.0', id: 'publish_guest_attribution_frontmatter', kind: 'breaking', text: "gbrain publish now recognizes a guest page saved from gbrain get, which starts with its [outside guest ...] warning line above the frontmatter. Before, the frontmatter after that line was not recognized and every frontmatter line, private values included, was published. Publish now drops the warning line and strips the frontmatter. If the frontmatter after the warning line never closes, publish refuses the page with invalid_frontmatter instead of publishing it; close it with an unindented --- line and publish again. Republish any guest page you shared this way before this release." },
  { since: '0.60.763.0', id: 'publish_refuse_wrapped_frontmatter', kind: 'breaking', text: "gbrain publish now refuses a page whose frontmatter sits below other text, such as the quote fence a paged gbrain get prints, with invalid_frontmatter. Before, that frontmatter was not recognized and every frontmatter line, private values included, was published. A frontmatter block counts when it starts in the first five non-blank lines with an unindented ---yaml, ---yml or ---json line, with an unindented --- line followed directly by a key: line or a { mapping, or with a pair of unindented --- lines that has a key: line between them. A page with an early horizontal rule still publishes when no Word: line follows the rule; a rule followed by a line such as Note: ... is refused, so reword that line or move the rule. Save the page with plain gbrain get or delete the lines above the frontmatter, then publish again. Republish any page you shared this way before this release." },
  { since: '0.60.764.0', id: 'brain_pdf_strips_private_sections', kind: 'fix', text: "PDFs made with the brain-pdf skill now leave out what gbrain publish leaves out: the Timeline, Facts and Takes blocks, HTML comments, citations and brain links, not just the frontmatter. The skill strips the page with the new gbrain publish --markdown, which writes the stripped markdown instead of an HTML page. A page whose frontmatter never closes is refused instead of rendered." },
  { since: '0.60.764.0', id: 'publish_wrapped_any_yaml_key', kind: 'breaking', text: "gbrain publish now refuses wrapped frontmatter whose keys start with a digit or a symbol, use a non-Latin letter, hold a space or carry a YAML anchor or tag, and an unclosed wrapped block that starts with a # comment line, with invalid_frontmatter. Before, those blocks were not recognized and their values were published. An early horizontal rule followed by any line with a colon and a space (for example Summary: ...) is now refused, so reword that line or move the rule. Publish whole pages only: a gbrain get --lines slice that starts below the opening --- holds frontmatter keys publish cannot recognize. Republish any page you shared this way before this release." },
  { since: '0.60.764.0', id: 'publish_wrapped_yaml_parse', kind: 'breaking', text: "gbrain publish now decides whether a block below other text is frontmatter with the YAML parser sync uses, instead of a key-line pattern. Before, wrapped frontmatter whose keys the pattern missed (an indented key block, a key holding a colon such as time 10:30:, a [a, b]: key, a block opened by a tag or anchor on its own line, empty-quoted, -: and ?: keys) was published with its values. A block between two unindented --- lines in the first five non-blank lines, or after an --- line that never closes up to the first blank line, is refused with invalid_frontmatter when it parses as a mapping or as a list holding one, or when it cannot be parsed and holds a colon followed by a space or the line end. An early horizontal rule followed by a list of Label: value items, or by a sentence YAML reads as a key and value (We met at 10:30 and agreed: ship it.), is now refused too, so reword those lines or move the rule. gbrain publish, in HTML and --markdown mode, also refuses with invalid_params, and writes nothing, when --out names the page itself through the same path, a symlink, a hard link or a case variant; before, the published copy replaced the page. Republish any page you shared this way before this release." },
  { since: '0.60.764.0', id: 'init_non_interactive_keeps_brain', kind: 'fix', text: "gbrain init --non-interactive with no engine flag now re-runs against the brain the config file already names: a PGLite brain at its configured database_path, or a Postgres brain at its configured database_url. Before, both stopped with \"--non-interactive requires --url\". An environment DATABASE_URL or GBRAIN_DATABASE_URL still wins, explicit engine flags still choose the engine, and with no config the command still asks for --url." },
  { since: '0.60.765.0', id: 'backup_coverage_failed_read_degraded', kind: 'fix', text: "The backup check no longer answers confidently when it could not read something. A backup-coverage read that fails now marks the verdict degraded (doctor says the database was unreadable during the check) or the item unknown (an install receipt or gbrain.yml that exists but cannot be read shows as an unknown row), in place of a confident answer such as a young, empty brain or no db_only tiering. A missing receipt or gbrain.yml is still simply empty, and a healthy check prints exactly what it did before." },
  { since: '0.60.765.0', id: 'doctor_missing_brain_health1', kind: 'fix', text: "gbrain doctor no longer creates an empty brain when your brain's folder is missing. When the config names a PGLite datastore that is not there (an unmounted drive or a moved folder), every doctor run that opens the database (plain, --json, --only connection and the other database checks, --remediation-plan, --remediate) now stops before it connects, exits 1 and prints the brain_missing error with reason missing_brain, the same reason gbrain serve gives. Before, doctor built a new empty brain at that path and reported it healthy with a score of 100. A failed check now says it could not read the brain instead of answering that the brain is empty. Mount the drive, move the folder back, or update database_path; gbrain init makes a new empty brain only when you choose to. doctor --fast and file-only checks never open the database and run as before. One case is not covered yet. A brain folder with no `PG_VERSION` that holds a stale, corrupt `.gbrain-lock` and an old-format `.gbrain-owner.json` still gets an empty brain from doctor, and a follow-up fix is planned." },
  { since: '0.60.765.0', id: 'entity_lookup_failed_degraded_contract01', kind: 'fix', text: "When the database read that finds an entity's page fails, `entity` (one name or `names`) now returns the degraded marker in place of \"No entity found\" / found:false with nothing marking it partial. The answer carries the degraded stage entity_lookup_failed (MCP `_meta.degraded` and a `[gbrain degraded: ...]` block, the CLI `degraded` key under --json or a stderr line), so a failed lookup is never read as \"this entity does not exist\". The exit code stays 0. A healthy lookup, hit or miss, is unchanged byte for byte." },
  { since: '0.60.765.0', id: 'skill_resolver_session_start_block', kind: 'add', text: "With skill loading on for Claude Code or Codex, the SessionStart hook now prints the skills pinned for that harness (gbrain skills pin add <id> --catalog claude-code-user or codex-user) and the text of the new setting skills.resolver.per_harness.<claude-code|codex>.session_start, on startup, resume, clear and after compaction. With no pins and no text the hook prints nothing, as before. An install whose hook doctor shows as outdated needs gbrain setup <harness> --skill-loading resolve once." },
  { since: '0.60.765.0', id: 'bundled_skill_json_skills_root', kind: 'add', text: "gbrain bundled-skill --json, with no skill name, now includes skills_root: the absolute path of the skills folder of the gbrain that is running (found from the running gbrain, not the current directory), or null for a single-file binary whose skills live only inside it. Tools that read gbrain's skills or skills/conventions can use it instead of walking up from the gbrain binary. Nothing else changes." },
  { since: '0.60.765.0', id: 'cross_modal_no_auto_retry_on_refusal', kind: 'fix', text: "The cross-modal-review skill no longer retries a refused review on other models by itself. The refusal_routing.behavior value next_in_chain and the chain list are removed from skills/conventions/cross-modal.yaml; a refusal is reported to the user, naming the model, and another model reviews only when the user picks one. A copy that still says next_in_chain is treated as report, and the agent says once that the option was removed. Nothing to do." },
  { since: '0.60.765.0', id: 'sync_restored_file_asks_first_lc1', kind: 'fix', text: "A file you restore after gbrain delete removed it (git checkout, a revert, or a commit that re-adds it) now goes through the file-drift consent step instead of being ignored. The next managed sync holds the file (file_drift, side deleted, state tombstone_edited, or purged_differs after the retention purge) and the page stays deleted. gbrain sources status and doctor list the hold, and gbrain repair file-drift --held --side deleted --state <state> --prefer file previews bringing the page back and does it only after you agree; --prefer database keeps the deletion and removes the file. The first managed sync after the upgrade reads the checkout once more, so it finds such a file even when nothing else changed. Before, sync settled the restored file as already up to date, and after the 72-hour purge the page was gone for good. A deletion that stands is unchanged: a delete that left the file (sync.write_through off, a read-only mirror), a delete whose removal is not committed yet, a --purge delete, and a git-canonical source settle with no hold." },
  { since: '0.60.765.0', id: 'search_supersession_currency', kind: 'fix', text: "When the check for pages a newer page replaced fails (in the ranking, or when a slug-shaped query puts a page in the top slot) (a statement timeout or a dropped connection), search and query now return the degraded marker supersede_check_failed (reason timeout or provider_error) in the response's degraded stages, and the degraded-recall notice says results may include outdated pages, in place of an unmarked ranking where the outdated page came first with no flag. The same rows come back either way; the marker only adds information. A supersedes link written while a server is running is now seen at once by the next search; a running server used to keep showing the outdated page as current for up to 5 minutes after the first link in the brain. Results on a healthy brain are identical." },
  { since: '0.60.765.0', id: 'cli_reads_through_live_pglite_serve', kind: 'fix', text: "While a gbrain serve holds a PGLite brain (the stdio server gbrain setup claude-code or codex starts for an agent session), everyday CLI reads (gbrain find, list, search, query, get, tags, links, backlinks, timeline, history, graph, whois, entity, search-exact and gbrain waiting) now go through that running server and print what they print with no server running, instead of refusing with pglite_busy. Admin commands that need the database to themselves still refuse as before, and so does a read run with read-affecting GBRAIN_* variables or provider keys the server does not share. A server started by an older gbrain answers owner_unavailable until it is upgraded and restarted." },
  { since: '0.60.765.0', id: 'skill_resolver_symlinked_skills_gst3459', kind: 'fix', text: "The skill resolver now indexes skills that are symlinked into a skills folder from somewhere else, the way gstack and other installers link their skills in from a checkout. Before, gbrain skills index build skipped every symlink that left the folder it was reading (symlink_outside_root), so a gstack install in ~/.claude/skills or ~/.codex/skills was almost entirely missing from the resolver. A symlink is followed only when it points at a skill folder (a directory with a SKILL.md) or at a SKILL.md file, and the skill is listed under the link's path; any other symlink that leaves the folder is still skipped. Your catalog picks the newly visible skills up on its next rebuild (gbrain skills index build, or the hook lane's automatic rebuild). To keep a linked skill out of the resolver, remove its link." },
  { since: '0.60.765.0', id: 'trajectory_lower_is_better_memory01', kind: 'fix', text: "gbrain eval trajectory, gbrain founder scorecard and the find_trajectory tool now know that for some metrics lower is better. For burn_rate, churn_rate, cac, burn, churn and any metric with the whole word cost, expense, loss, latency, payback or debt (or costs, expenses, losses, debts) unless the name also has saving, savings, saved, recovered, recovery, reduction, reduced, avoided, coverage, ratio or ratios (so cost_savings, revenue_loss_recovered, debt_service_coverage_ratio and benefit_cost_ratio stay ordinary metrics), a drop is no longer a regression or red flag; a rise of 10% or more is, and the scorecard says \"burn rose 33.3%\". Every other metric still flags a 10% drop. A series of a lower-is-better metric that starts negative (a loss stored as -50000) compares magnitudes at every step, chosen once per series: -50000 to -100000 is a +100% rise, -50000 to a profit of 100000 is an improvement, and 100000 back to -50000 is a rise. A series that starts positive uses the plain change. A change of exactly the threshold is flagged even when float rounding puts it a hair under (0.05 to 0.055). Each regressions entry gains an optional direction field (down or up); schema_version stays 1. The scorecard's growth delta also divides by the absolute prior value, so a loss shrinking from -100000 to -50000 reads up." },
  { since: '0.60.765.0', id: 'engine_status_brain_ref', kind: 'add', text: "New: gbrain engine status --probe prints brain_ref (JSON probe.brain_ref, human line Ref:), a one-way 16-character digest of the brain's persistence identity, never the identity itself. A PGLite gbrain serve now writes a private 0600 file next to the brain at start (<data dir>.gbrain-brain-ref.json) holding that reference and a digest of its lock token, so the probe can report the reference while the serve holds the brain." },
  { since: '0.60.765.0', id: 'engine_swap_plan_s5a', kind: 'add', text: "New read-only command: gbrain engine swap --to rust --plan (alias --dry-run, add --json for one JSON document) shows whether this brain is ready to move to the opt-in Rust engine. It lists the verdict, each readiness criterion with what was measured or which evidence is missing, the variables and gbrain service definitions on this machine that select the current engine (names only, never values), the free disk space and a plan hash. Speed is reported and never blocks the opt-in move. It writes nothing and never creates a brain: a mounted brain is refused with engine_swap_refused, reason team_brain, and a configured path with no brain in it is refused with no_brain. A brain that uses managed storage is refused with engine_swap_refused, reason managed_storage, because the Rust engine never holds managed storage. While a gbrain sources refresh is unfinished it refuses with engine_swap_refused, reason refresh_unsettled, and names each refresh and the command that finishes it. READY needs current follower evidence and exactly one observed writer host. The move itself (--yes --expect) arrives in a later release; any other flag is refused as invalid_params." },
  { since: '0.60.766.0', id: 'refusal_stops_step_gst3583', kind: 'fix', text: "Bundled skills now treat a model provider's refusal as the end of that step: the agent reports it to the user, naming the model, and does not rerun the request on another model. This replaces the earlier wording that let another model review a refused request when the user picked one. Nothing to do." },
  { since: '0.60.767.0', id: 'mention_pass_bounded_gst3609', kind: 'fix', text: "The mention pass (gbrain extract --stale, the cycle's extract phase) now always says why it stopped and no longer gets stuck on a large source. A throw or an abort in the alias refresh, the name-list save or the reconcile now records state failed with the step and the error on the source's mention index status; before, the status kept saying pending with no error, so a pass that died every run looked like a slow one. The scan for pages naming a newly added name now has half the time left in the run. When it stops early, the name list is still saved and the pages it did not reach are marked for the reconcile, which works through them in batches across runs; before, that scan had no time limit, so on a large source it could use up every run and nothing drained. A pass with no time left does not start that scan, and a source whose changed name list it left unsaved stays pending with its last pass time unchanged, instead of reading complete. Nothing to do; a source stuck pending since an earlier release starts draining on the next runs." },
  { since: '0.60.767.0', id: 'mentions_skip_retired_pages_gst3609', kind: 'fix', text: "A page that hands its identity to another page (frontmatter merged_into, superseded_by, canonical: false, or a status naming it an alias or redirect) no longer collects mention links. Before, its title, aliases and X handle stayed in the mention name list, so text naming that person or company kept linking to the retired page, and when the retired page and the page it points to claimed the same alias or handle, neither linked through it. Now the name list leaves retired pages out, so their names link to the page that claims them (add the retired page's name to that page's aliases to keep it), and the next mention pass (gbrain extract --stale) moves existing mention links off retired pages. Ranking, entity lookup and link resolution already followed these redirects. No page is edited." },
  { since: '0.60.767.0', id: 'slug_reads_normal_form', kind: 'fix', text: "Slug reads now normalize a slug the way writes do: lowercase, with accented letters composed (Unicode NFC). A read keeps the page the old read found, then tries the normalized spelling, so gbrain get People/Alice-Example finds people/alice-example and a decomposed accented slug (as macOS file names are) finds its page. A put with the decomposed spelling of an existing accented slug no longer creates a second page that prints the same name; a put by the exact capitalised or decomposed spelling of a page stored that way before this release is refused (`invalid_params`, detail `legacy_slug_spelling`), even when its composed twin exists, until a later fix moves it. Pages stored under capitals or decomposed form still open by that exact spelling, and deleting, restoring, tagging, untagging, adding a timeline entry to, editing or appending to one by that spelling changes that page in place; a file upload, an ontology fact or `gbrain takes horizon set|clear` by that spelling acts on that page too. For a page stored with capitals, those writes by its exact spelling answered page not found before; they now change that page, and no lowercase second page is written. A slug prefix reads every spelling that holds pages, so no stored page hides. A managed import that would write a composed twin of such a page stops with a message saying how to fix it. A read of the normal form that finds nothing now opens the one other stored spelling, honouring alias, source and include_deleted. Only when no page is found that way and two readable stored pages normalize to the slug is the read refused (`invalid_params`, detail `ambiguous_slug`), naming the first two spellings; before, that read answered page not found. remember through an entity alias writes to the page in place. Facts saved under an accent-folded slug before this release still show on recall and the card." },
  { since: '0.60.767.0', id: 'keyless_by_choice_not_degraded_gbra585', kind: 'fix', text: "On a brain whose embeddings were turned off on purpose (gbrain init --no-embedding), search, query, find_experts and recall are keyword-only by design, so their results no longer carry the [gbrain degraded: ...] stamp or a degraded_recall notice, and the keyword arm finding nothing is not degraded either. An empty result now says the search was keyword-only and no page the caller can read holds those words. _meta.retrieval still records the keyword-only run. A brain with no embedding provider configured, a timed-out embed or a failed search arm is stamped exactly as before." },
  { since: '0.60.767.0', id: 'skill_resolver_session_budget_8000_gst3459', kind: 'default', text: "The skill resolver's per-session budget for skill lists, skills.resolver.session_token_budget, now defaults to 8,000 tokens instead of 2,000. At 2,000 a long session ran out around its twentieth turn and then stopped offering skills; at 8,000 it lasted all 30 turns of the measured sessions. It applies to every caller that reads the default: the Claude Code, Codex and Hermes hooks, the OpenClaw plugin, the Pi extension and gbrain skills resolve. A list still counts against the budget the same way, and a session still shows fewer skills as it spends more. To keep the old limit, run gbrain config set skills.resolver.session_token_budget 2000." },
  { since: '0.60.767.0', id: 'init_keeps_existing_rust_brain', kind: 'fix', text: "gbrain init (and gbrain init --non-interactive) with no engine flag on a brain whose config says engine \"rust\" now reports the existing Rust brain and leaves config.json unchanged; it never opens the Rust store. Before, plain init rewrote the config to engine \"pglite\" and --non-interactive stopped to ask for --url. Pass --pglite, --supabase or --url to switch engines explicitly." },
  { since: '0.60.768.0', id: 'dedupe_same_source_split_gst3609', kind: 'fix', text: "The duplicate finder (gbrain dedupe --preview, doctor entity_duplicates) now also lists two or more same-name pages of one source as their own in_source group when they sit in a cross-source group, so they show up for collapsing. Before, they appeared only inside the cross-source group, and gbrain dedupe confirm on that group would have linked two pages of one source as one identity. Now confirm refuses such a group (reason same_source_members) and the confirm list leaves it out: collapse the same-source pages first, and the next preview shows the cross-source group with one page per source. Nothing is linked, merged or edited by this change." },
  { since: '0.60.768.0', id: 'ghost_pages_only_copy_gst3637', kind: 'breaking', text: "gbrain repair ghost-pages now soft-deletes a page only when a commit deleted its file, because only then does Git still hold what the file held. Three kinds of page it used to remove are now listed apart and kept. ghost_never_committed: no commit ever held the file, or sync last imported it from uncommitted working-tree bytes that the deleting commit never held, so the page holds the only copy; write the file from the page with gbrain repair file-drift --source <id> --slug <slug> --prefer database, then commit and sync. ghost_worktree_only: the file is gone from the working tree but HEAD still holds it; restore it with git checkout HEAD -- <path> and sync, or commit the deletion, sync and preview again. ghost_history_unknown: Git cannot say which commit deleted the file (a shallow clone, a folder that is not a Git checkout, or a failed history read); write the file from the page, fetch the full history and preview again, or, outside Git, delete the page by hand if that is intended. gbrain repair file-drift --prefer file skips these pages with the same codes. An approval saved before upgrading is refused at apply for these pages, with the same code." },
  { since: '0.60.768.0', id: 'pg_url_raw_at_redaction_gst3639', kind: 'fix', text: "Database URLs whose password contains a raw, unencoded @ are now redacted whole in gbrain's output. Before this release, config get database_url, engine status --json, doctor, and the init, db-repair and migrate-embeddings notes cut the password at its first @ and printed the rest of it after the *** marker. If your database password contains a raw @ and you have shared that output, the part of the password after its first @ may have been visible there." },
  { since: '0.60.768.0', id: 'strict_since_limit_values_gst3639', kind: 'fix', text: "A --since date that is not a real calendar day, such as 2026-02-30, is now refused with a usage error by agent logs, access read-log, beliefs, repair and recall, and by the recall tool's since parameter. Before, the date rolled over into the next month and the command quietly used a different window. The code-callers, code-callees, code-def and code-refs commands now refuse a --limit that is not a whole number of 1 or more, or that has no value, instead of failing with an unknown error or quietly reading 5abc as 5, 0 as an empty list and 1.5 as 1." },
  { since: '0.60.768.0', id: 'secret_scan_url_raw_at_gst3639', kind: 'fix', text: "The secret scanner now redacts the whole password in a database or https URL when the password contains a raw, unencoded @. Before this release, it cut the password at its first @, so the rest of the password stayed visible after the redaction marker in the text gbrain redacts with it, such as search output and rendered transcripts. Such a finding also gets a new fingerprint. An allow entry pinned to the old fingerprint stops matching, and the scanner reports the new one to allow." },
  { since: '0.60.769.0', id: 'dedupe_classes_gst3609', kind: 'add', text: "gbrain dedupe classes counts the pairs of person pages that might be one person by their evidence (shared email, phone or account id, your email and chat pages, and an opt-in Exa web search), and gbrain dedupe sample --class <c> exports a seeded random sample of one class to check by hand. Both only read; nothing is linked. Web search is off until you set EXA_API_KEY and run gbrain config set dedupe.exa on; it sends only a name plus one company or job title, never for a page not every reader may read or a family or minor page, caches every answer and stops at dedupe.exa_run_cap (2,000) and dedupe.exa_total_cap_usd ($25). Run gbrain dedupe classes --exa --dry-run to see the cost first." },
  { since: '0.60.769.0', id: 'google_contacts_identity_links_gst3609', kind: 'add', text: "gbrain dedupe link-contacts --source <id> counts how a Google source's contact pages would link to your person pages, and --apply links each one to the one person page with exactly the same email or phone, then keeps the contacts each sync changes linked (google_contacts.identity_links). Two or more matches, or one person whose page has another name, wait for you in gbrain sync status, a name alone never links, and no page is edited. gbrain dedupe reject on a contact and person pair now removes that link for good, for Apple Contacts links as well. --unlink removes every link the source made." },
  { since: '0.60.769.0', id: 'timeline_split_not_drift', kind: 'fix', text: "A page whose database row keeps its timeline inside the body (an import before v0.46.25.0 left a bare dated ## Timeline section there with an empty timeline) no longer counts as differing from its file when the file holds the same text and only the split differs, which is how today's parser reads such a file when it has no timeline sentinel. Writes to such a page (remember, put_page, timeline entries, maintenance writes) are no longer refused source_changed (file_database_drift), and sync imports the next edit of its file instead of holding it file_drift. A file_drift hold an earlier release wrote is re-checked only when someone asks (gbrain sources retry-held, or the release below), never by a plain sync. A hold on a file unchanged since its import (database side) is never imported over by sync on its own: gbrain repair file-drift --source <id> --held lists the ones whose page and file now agree as release_hold, and gbrain repair file-drift --source <id> --slug <slug> --prefer file previews their release; the release, like gbrain sources retry-held, now re-checks such a hold and imports only when the file holds the page, and holds it again otherwise; a pending write waiting for its Git publish and a page under storage.db_only keep their database copy. A file over the 24 MiB in-memory sync limit whose page also changed in the database is held file_drift instead of streamed over the database copy. Any line that differs still refuses as before." },
  { since: '0.60.769.0', id: 'sync_freshness_usage_limit_gst3452', kind: 'fix', text: "`gbrain doctor` sync_freshness no longer fails a connector source whose first sync is still in progress. A source whose last sync stopped only at a provider usage or rate limit (gbrain.io's daily allowance, Google's quota) with nothing else failed, and whose limited runs landed pages inside the fail age, now reads `warn` (`sync_usage_limited`) and says the next sync resumes it. A source whose sync job is running now reads `warn` (`sync_first_run_in_progress`) even when no sync lock is held at that moment. Failed items, held files, a bare permission error (403) and limited runs with no pages landed inside the fail age still read `fail` (`sync_no_successful_sync`)." },
  { since: '0.60.769.0', id: 'held_writes_follow_page_rename', kind: 'fix', text: "A fact or take the write gate holds for your review now stays held when its page is renamed, and a different page that takes the old name does not inherit it. Releasing a held fact publishes it on the page it was held for, under that page's current name, and is refused when that page no longer exists. On upgrade, existing held writes are matched to their page; any that cannot be matched to one page stay held for every page they could belong to and are listed by gbrain doctor as write_gate_hold_ambiguous, so you can review and drop them with gbrain trust review." },
  { since: '0.60.769.0', id: 'engine_writer_observations_s5', kind: 'add', text: "Three new tables, engine_writer_observations, engine_writer_sessions and engine_writer_coverage_gaps, and one function, gbrain_note_writer, are added to every brain by a schema migration. They stay empty unless you turn on Rust engine shadow mode (gbrain engine shadow start). While shadow mode is on, each gbrain process that writes to the brain notes one row (its host id, the name its database connections carry, its command kind, its gbrain version, and when it first and last wrote), at most every 10 minutes and after its write committed. On a Postgres brain, shadow start also adds one trigger to every brain table that records which database connections write (never failing a write, and waiting at most 50 ms on its own tables), and shadow stop removes those triggers. They hold no page content, paths or query text." },
  { since: '0.60.770.0', id: 'ghost_pages_moved_kept_gst3623', kind: 'fix', text: "gbrain repair ghost-pages no longer approves a page whose file moved to another live page for soft-delete: the preview lists it as moved_to with the gbrain repair moved-pages --source <id> --slug <slug> fold, which previews first, and keeps a page whose path Git renamed or copied without a proven fold as move_unproven. A database_ahead_of_file ghost now shows move evidence, matched or unmatched. gbrain repair moved-pages also folds a file renamed and edited in one commit, or a page edited in the database after its move, when the moved page holds every line of the old page in order, with its tags; a move whose lines changed stays held. Nothing is folded or deleted without a preview and its --expect hash." },
  { since: '0.60.770.0', id: 'sync_freshness_usage_limit_followups_gst3452', kind: 'fix', text: "`gbrain doctor` sync_freshness keeps the `sync_usage_limited` warning for a connector first sync through any number of reruns that hit the spent limit, and through skipped or queued runs, while a limited run that landed pages is inside the fail age. A run with writes still pending no longer counts as landing pages. A sync job that holds its job lock but has run past the staleness ceiling now reads `fail` (`sync_no_successful_sync`) with a `gbrain jobs get` fix instead of `sync_first_run_in_progress`." },
  { since: '0.60.770.0', id: 'learned_view_nightly_ledger', kind: 'add', text: "New: the dream cycle has a learning_derive phase that notes what each night learned (facts an extractor added, promises owed to you, facts that disagree, thin pages enrichment filled, and Facts rows you typed) as id-only pointers in a new learning_items table, and gbrain learned (MCP tool learned) lists the ones you have not seen yet, rendered live from each fact, loop, proposal or page, so anything you forget, purge or make private drops out. gbrain learned --since <date> lists everything since then and --stats shows per-night counts. Nothing is sent anywhere and nothing paid runs; the phase is free and adds one small table." },
  { since: '0.60.770.0', id: 'enrich_thin_owner_contact_default', kind: 'default', text: "The enrich_thin phase (still off unless you set cycle.enrich_thin.enabled true) now fills first the thin person and company pages of people you actually deal with: the new owner-contact order ranks pages by meetings, conversations, email threads and chronicle events from the last 90 days that link to or mention them, by open loops with them, and by a link to or from your own page, and ranks fuller pages lower. It becomes the phase's default order when gbrain can find your own page (gbrain identity names it) with no conflict; otherwise the phase keeps the inbound-links order. A cycle.enrich_thin.order you set always wins: gbrain config set cycle.enrich_thin.order inbound-links keeps the old order. Two new optional daily caps, cycle.enrich_thin.max_daily_cost_usd and cycle.enrich_thin.max_daily_pages, stop the phase for the rest of your day (brain.timezone, UTC when unset) across every run; unset, there is no daily cap, as before." },
  { since: '0.60.771.0', id: 'ghost_pages_move_gaps_gst3648', kind: 'fix', text: "gbrain repair ghost-pages now also keeps a page whose deleting commit rewrote another file to its content (moved_to or move_unproven), keeps a page with more than five same-name files as move_unproven, and checks the move again when a commit lands between preparing and writing a soft-delete. With sync.apply_held_deletions on, a held page whose file moved stays held, refused as file_moved, and a held deletion is passed over (the page stays held, the rest of the pass publishes, a later sync checks it again) when a commit lands before it publishes. Nothing extra is deleted; some pages that were approved for soft-delete before are now kept." },
  { since: '0.60.771.0', id: 'member_keys_personal_sources_gst3747', kind: 'breaking', text: "A key bound to a member other than the brain owner that has no source list (for example a token from gbrain auth create --member) no longer reads another member's personal source, a source bound with gbrain access member source add, even when that source is federated. Before, such a key read every federated source, other members' personal sources included. It still reads its own member's personal sources and every shared source, and a local stdio server bound to a member follows the same rule. The owner and every key bound to the owner lose nothing (the owner is the member gbrain access owner set named; with no owner set, every member-bound key takes the rule), and a key whose source list names a personal source keeps reading it. To let a key read another member's personal source on purpose, name it in the key's grant: gbrain auth rescope --token <name> --sources <write-source>,<personal-source>. gbrain access check --token <name> shows what a key reads now." },
  { since: '0.60.771.0', id: 'doctor_missing_brain_followup_10114', kind: 'fix', text: "gbrain doctor now refuses a missing brain in three more cases. A brain folder with no PG_VERSION that still holds a leftover .gbrain-lock whose metadata cannot be read is refused as brain_missing; before, the leftover lock read as held and doctor built an empty brain. When the folder is moved or unmounted while doctor waits for the datastore's lock, doctor checks again once it holds the lock, refuses, releases the lock and creates no datastore; the empty .gbrain-owner.lock file beside the folder can still be left behind. With --alert (and --alert --json), a missing brain is reported with the alert contract: exit 17, alert level act, and one brain_missing item, so a heartbeat pages on it; without --alert, doctor still exits 1 with the same brain_missing error." },
  { since: '0.60.772.0', id: 'chat_fallback_refusal_default_off_gst3752', kind: 'default', text: "chat_fallback_on_refusal now defaults to false. If you set a chat_fallback_chain, a request that one model refused on safety grounds (a refusal or content-filter stop, or a provider content block such as a content-policy 400) now comes back to the caller as that refusal instead of being sent to the next model in the chain. Errors still fall back exactly as before: rate and subscription limits, outages, timeouts and rejected keys move to the next model. An explicit true is kept wherever it is set (GBRAIN_CHAT_FALLBACK_ON_REFUSAL, config.json or the brain database). To send refused requests to the next model again, run gbrain config set chat_fallback_on_refusal true. A brain with no chat_fallback_chain is not affected." },
  { since: '0.60.772.0', id: 'google_contact_mirrors_link_gbra782', kind: 'add', text: "Google contact linking now counts copies of one person page held in several sources as one person. When the copies share the slug, the matched email or phone and an agreeing name, the contact links to the default source's copy instead of waiting for a decision. Copies that disagree, or that you marked as different people, still wait. Decide the rest with gbrain dedupe decide; gbrain dedupe undo reverses any choice." },
  { since: '0.60.772.0', id: 'enrich_evidence_page_readers_gst3815', kind: 'fix', text: "gbrain enrich and the autopilot thin-page phase now fill a page only from facts, link context and search hits that every reader of that page can already see, and a page that names readers or sits under a folder rule only from pages labelled for all of its readers. Before this release they also used private facts, private rows and takes from the page itself, and text from pages that name fewer readers, and wrote the result onto the page under its own readers. Pages filled before this release keep their text: if you ran gbrain enrich or turned on cycle.enrich_thin on a brain with private pages or readable_by labels, review the pages whose frontmatter has enriched_by: cli:enrich and remove anything their readers should not see." },
  { since: '0.60.772.0', id: 'ghost_pages_merge_readd_split_gst3688', kind: 'fix', text: "gbrain repair ghost-pages now keeps a page whose content a merge commit rewrote another file to or added as a new file (move_unproven), and gbrain repair moved-pages folds a move onto a path deleted and added again only when that path's page holds every line, the type, the tags and the frontmatter of the old page (else survivor_differs). With sync.apply_held_deletions on, a sync deletes only a page an earlier sync already held, so a file moved in two commits is kept as file_moved when the add lands before that later sync. A held page is now deleted one sync later than before; on a checkout where nothing else changes that is the next commit or the daily full sync, up to about a day. Nothing extra is deleted." },
  { since: '0.60.772.0', id: 'show_user_relay_whole_gbra789', kind: 'fix', text: "The text gbrain asks your agent to show you (the [SHOW USER] part of an [AGENT] block) is no longer cut at 1,000 characters. gbrain setup and gbrain init used to end their first-run summary mid-number (\"conservative $4 / $80 / $16…\"), so the closing line \"Nothing needs an answer now\" never arrived. The relay now carries up to 4,000 characters, and marker text inside it is still neutralised." },
  { since: '0.60.772.0', id: 'keyless_no_embedding_held_notice_gbra789', kind: 'fix', text: "On a brain with embeddings off on purpose (gbrain init --no-embedding), search and query no longer print \"[gbrain degraded: held_files]\" saying pages are held from embedding, and no longer suggest gbrain embed --held. Such a brain never embeds anything, so a held page is not missing from any search it can run. _meta.retrieval.coverage drops its embedding_held count there too. Brains with embeddings on keep the notice and the count." },
  { since: '0.60.772.0', id: 'transcripts_try_it_get_gbra789', kind: 'fix', text: "gbrain transcripts ingest now ends with \"try it: gbrain get <slug> --source-id <source>\" naming the page it just wrote and the source it went to, so a shell pinned to another source still opens it. It used to suggest gbrain query \"<slug>\", a keyword search for the slug string that found nothing useful." },
  { since: '0.60.772.0', id: 'learned_window_brain_start_gbra789', kind: 'fix', text: "gbrain learned and gbrain learned --stats no longer name a start date older than the brain. On a brain created minutes ago they used to say \"Nothing new learned since\" a date seven (or thirty) days back; the default window now starts when the brain was created (its earliest source) when the brain is younger than the window. The since field in --json moves the same way. An explicit --since is unchanged." },
  { since: '0.60.772.0', id: 'status_keyless_repo_less_gbra789', kind: 'fix', text: "gbrain status run on the brain's own machine no longer makes a healthy keyless brain look broken (a thin client reading a remote brain still shows the old lines). A source with no local folder and no connector (Slack, meetings, iMessage, contacts), which keeps its pages in the database, that has never synced now reads \"[OK] <source> repo-less (pages live in the database; nothing to sync)\" instead of \"[UNKNOWN] <source> never\", and a brain with embeddings off on purpose shows embed=off instead of embed=0%. A default source whose checkout gbrain import recorded keeps the old line. A full gbrain dream cycle over the whole brain (no --source or GBRAIN_SOURCE, run from outside a source's own folder) that ran to its end (ok, clean or partial, never aborted) now records itself (config dream.last_full_cycle), so \"Last full cycle\" shows the newer of that record and autopilot's last cycle instead of \"never run\"; status --json carries it under cycle.last_full with name dream, plus repo_less_sources and embeddings_off." },
  { since: '0.60.772.0', id: 'pointers_name_exact_calls_gbra789', kind: 'fix', text: "The brain-page pointers gbrain adds to an agent's turn now name calls that work. A page pointer reads \"use get_page {slug: \"<slug>\"} before relying on details\", and the pointer block adds \"If get_page is not in your tool list, call request_tools {tools: [\"get_page\"]} first; if it still is not callable, this connection cannot open pages, so say that rather than answer from memory.\" for the starter tool list, where get_page is not listed. Entity cards in context_pack and turn context read \"use entity {name: \"<slug>\"} or get_page {slug: \"<slug>\"}\", with source_id when the card is from another source. entity called with slug instead of name now says \"entity takes name, not slug.\" and names the exact entity {name: ...} call. No tool grant changed." },
  { since: '0.60.772.0', id: 'setup_failed_import_exits_nonzero_gbra789', kind: 'fix', text: "gbrain setup now exits 1 when an import you asked for with --notes, --docs or --transcripts fails, and prints one line on stderr naming the folder, the error and the import command to run again. It used to exit 0 with the failure only inside its report. A --docs or --transcripts import that could not run because the company source could not be set up counts as failed too. An unreadable folder is now a failed import (\"cannot read <folder>: EACCES\") instead of \"import 0 file(s)\". The harness wiring and every other step that finished stay in place, and --json still prints one document whose brain_layout names the failed import." },
  { since: '0.60.772.0', id: 'container_copy_names_self_transfer_gbra789', kind: 'fix', text: "A prebuilt brain copied into a container (its checkout and the ownership reservation beside it, now on another filesystem device) used to refuse its first write with a generic recovery_required and no way out. It now refuses with detail physical_root_directory_changed and names the relocated-root self-transfer (writer transfer prepare and accept with --self-transfer --confirm-relocated-root), which re-stamps the path once per container. A stamp that disagrees with its reservation, or a malformed device, still gets the generic refusal." },
  { since: '0.60.772.0', id: 'legacy_slug_put_names_repair', kind: 'fix', text: "A put_page by the older spelling of a page stored under capitals or a decomposed accent, and an import of its file, still stop and change nothing, but the message now says how to move the page: preview gbrain repair slug-spelling --source <id>, then run the apply command it prints after the owner agrees. On a managed brain the message says a person has to decide how to rename the page. The moved page keeps its id, history and attachments, and its old spelling keeps opening it." },
  { since: '0.60.772.0', id: 'nightly_learning_defaults', kind: 'default', text: "The dream cycle now finds facts that disagree by default. dream.claim_conflicts.mode unset now means propose: each cycle files a pending proposal when two typed facts about the same thing disagree. It needs no key, costs nothing and changes no fact until you decide (gbrain trust review --kind contradiction). While a proposal is pending, recall and search mark the facts in it as contested. Turn it off with gbrain config set dream.claim_conflicts.mode off; a value you already set is kept. Thin-page filling (cycle.enrich_thin) is still off until you turn it on, and its brain-wide cap per cycle run (cycle.enrich_thin.max_total_cost_usd) now defaults to $0.50 instead of $5.00; a cap you set is kept. gbrain doctor now reports the newest nightly learning run and how much of the morning note you kept or undid (learning_note)." },
  { since: '0.60.772.0', id: 'learned_keep_undo_push', kind: 'add', text: "New: gbrain learned-keep and gbrain learned-undo (MCP tools learned_keep and learned_undo) answer the morning note. Keep marks what the nightly run learned as right and changes nothing else. Undo reverses an item through the command that owns it: a new fact is forgotten, a promise is closed as dropped, and a filled-in page goes back to its earlier version unless it was edited since. Agents that load gbrain's context at session start also get one line saying how many new things are waiting, with no item text, until the note is shown; gbrain config set learning.note.push false turns it off. Items nobody saw expire after 7 days." },
  { since: '0.60.773.0', id: 'agent_policy_l1_gst3824', kind: 'add', text: "New: an agent policy says when your agents may send, spend, delete, sign up, call or publish for you outside the brain. gbrain policy init sets one (the default preset asks before every such action), gbrain policy allow, ask and deny change one rule, and gbrain policy show prints it. Agents ask with the policy_check tool (or gbrain policy check) and get allow, ask, deny or none. It is advice only: your harness's own approvals still apply. A change from an agent session, or with no terminal, waits as a pending revision until you run the printed gbrain policy accept command in your own terminal or approve it in the owner session, and remote callers can never write the policy page. The terminal check stops agent sessions that keep their usual markers; it is not proof against a program running on the brain host that hides them. The capabilities tool tells an agent which gbrain tools its connection can call right now, listed or not. A brain-first line that tells agents to call policy_check first is off by default; gbrain config set brain_first.policy_line on adds it at the next setup or upgrade, and off removes it." },
  { since: '0.60.773.0', id: 'dedupe_auto_links_gst3642', kind: 'add', text: "gbrain dedupe auto lists the pairs of person pages it would link without you (today C2: an email or phone only those two pages hold, in two sources) and gbrain dedupe auto --apply links them, each as an undoable decision (gbrain dedupe undo <id>); gbrain dedupe auto --off C2 removes every such link and stops it. gbrain dedupe classes now leaves out a page's copy kept under the same slug in another source, and holds back pairs whose shared id a page with another name also carries, or whose page is a room, a team or a mailbox." },
  { since: '0.60.773.0', id: 'dedupe_auto_collapse_gst3642', kind: 'add', text: "gbrain dedupe auto now also collapses two person pages in one source with the same name and a shared id, email or phone (class C7). The newer page gets merged_into pointing at the older one, which takes its title as an alias. Nothing is deleted, and with a repository each collapse is one commit. gbrain dedupe undo <collapse id> or reject <collapse id> takes one back, and gbrain dedupe auto --off C7 takes back them all. Like C2 links, nothing changes until you run gbrain dedupe auto --apply. Automatic C2 links also hold back a few more pairs. A phone extension is its own number, distinct_from holds across sources, a rejected pair stays apart after a rename, and a title with a digit or a lone first name no longer reads as a handle." },
  { since: '0.60.773.0', id: 'setup_codex_registers_full_i1', kind: 'default', text: "`gbrain setup codex` now registers `serve --surface full` by default, so a new Codex connection lists every tool gbrain serves instead of the starter set (`serve --surface starter --advertise verbs`). Codex does not reload its tool list, so the tools `request_tools` unlocked on starter never reached it. The wider surface grants nothing a starter session could not already reach on stdio by calling `request_tools {\"surface\":\"full\"}`: read-only connections, credential scopes, publish gates, page readers and the session's source still apply. When `mcp.allow_session_widen` is off (`gbrain config set mcp.allow_session_widen false`, read from the brain database first and then the config file, with the values `gbrain serve` reads as off), setup keeps starter as the Codex default, since full would lift that ceiling; if setup cannot read the brain database (a running gbrain server holds it), a new Codex entry gets starter, an existing one stays as it is, and setup prints a note; `mcp.default_surface_codex full` or `--surface full` still picks full. The Codex receipt now records `surface_origin` (`explicit` when you passed `--surface`, `default` when setup picked it). Pin the old registration with `gbrain setup codex --surface starter --advertise verbs`; `--advertise` is new and keeps the listing you pass. `gbrain config set mcp.default_surface_codex starter` turns the Codex default back for every later setup run, and `gbrain config unset mcp.default_surface_codex` restores the shipped default; `mcp.default_surface_claude_code` and `mcp.default_surface_hermes` do the same for those harnesses. Claude Code, Hermes, opencode and other hosts keep registering starter." },
  { since: '0.60.773.0', id: 'setup_codex_rerun_moves_default_i1', kind: 'action', text: "Re-running `gbrain setup codex` on an entry it wrote with `surface_origin: default` moves that entry to the current Codex default (now `serve --surface full`) and prints the move with the exact command that keeps the old entry, including its `--source`. An entry whose receipt predates `surface_origin` keeps its surface; setup prints the command that would move it to the Codex default, so run that line if you want the full tool list in Codex. A surface you chose with `--surface` (origin `explicit`), an entry another tool owns and a hand-written entry stay as they are. `gbrain setup openclaw` prints an `openclaw mcp set` line when your OpenClaw config holds a starter gbrain entry and never edits OpenClaw's config; the OpenClaw docs now register `--surface full`." },
  { since: '0.60.773.0', id: 'keyword_count_cli_9412', kind: 'add', text: "gbrain search and gbrain query now print how many pages contain the query's words (a literal match) on stderr, so an agent on the command line can tell \"the brain has no page with these words\" from \"a few pages matched by meaning\". When no page contains the words, the query names no known entity and rows still came back, the line reads \"No page contains these words (literal match). The rows below matched only by meaning.\" Plain --json still prints the bare result array; --json --timings adds keyword_matches, which is counted (with the total), capped (with the cap) or unavailable (never a count of zero). The query tool over MCP now runs the same count as search and shows the same \"Keyword matches\" line, pointing at search with match \"keyword\" for the full list." },
  { since: '0.60.773.0', id: 'portable_profile_core_p1', kind: 'add', text: "New: a portable profile. remember takes a facet (size.<item>, brand, diet, allergy, style, constraint, schedule, household, other); with no entity it saves the fact on your own profile, which is memory/owner on a single-user brain, the owner's entity for the brain owner and the member's own member page for a member credential. Allergy facts are saved private unless the call names a visibility. Any connected agent reads the profile with context_pack and profile set to true (one block of facets, constraints, relationships from your page's links, unfaceted preferences and a withheld count, packed into budget_tokens), and the CLI reads it with gbrain profile. A remember without facet is unchanged. The claim metric prefix profile. is now reserved: a hand-written claim_metric that starts with it is refused (profile_metric_reserved, with the same call using facet as the fix), an unknown facet is refused with the list (profile_facet_unknown), a member credential cannot save a profile fact onto another page (profile_entity_not_self), and facts extracted from conversations never carry the prefix. find_trajectory, gbrain eval trajectory and the founder scorecard skip profile facts. On a brain with no members, an agent connected without an owner binding cannot read the owner's private profile facts: they stay private, withheld counts them and a profile_private_hidden notice names gbrain access owner set. Existing grants made from a bot profile keep their tool list; the new parameters ride on remember and context_pack, which they already call." },
  { since: '0.60.773.0', id: 'skill_resolver_vectors_gst3568', kind: 'default', text: "The skill resolver now ranks Claude Code and Codex skills by meaning as well as by words when your brain has an embedding model (embedding_model in ~/.gbrain/config.json). To do that, each message in those harnesses is sent to the brain's embedding provider (Voyage, OpenAI or Google), and each skill index build sends your skills' names, descriptions and the start of their bodies once. A brain with no embedding model, or with embedding_disabled, keeps word matching only and sends nothing. A turn waits at most 1.5 seconds in Claude Code and 2 seconds elsewhere, and any failure answers with the word matcher's exact output. See docs/guides/skill-resolver.md, \"Skill vectors\"." },
  { since: '0.60.774.0', id: 'get_page_grep_alternatives_3786', kind: 'fix', text: "get_page grep (gbrain get --grep) now treats an inner pipe as alternatives: a term such as uptime|SLA matches paragraphs holding either word, as well as the literal text, and the response lists the words in grep.alternatives. A spaced pipe (a | b, a table row) or a leading or trailing pipe is still matched literally." },
  { since: '0.60.774.0', id: 'household_records_gst3825', kind: 'add', text: "GBrain now keeps household records: bills, supplies, birthdays, school deadlines, appointments, returns and store credits, as pages of type household. `household_due` (on the starter tool list, and `gbrain household due`) ranks what is overdue, at risk or coming up, each with a reason and a proposed action that always needs the user's yes; `household_add` and `household_mark` (and `gbrain household add|mark|list`) write them. On a brain that serves several people, each record's readers are recomputed from the placement table on every write: money, returns and anything about a child are adults only, and a record about a subject GBrain cannot classify stays adults only. GBrain never buys, pays, books, calls or sends. Guide: docs/guides/household.md." },
  { since: '0.60.774.0', id: 'google_consent_read_only_gst3849', kind: 'default', text: "gbrain google connect and setup now ask Google for exactly the read-only scopes they need and no longer merge earlier grants of the same OAuth client (include_granted_scopes=false). A consent, import or token refresh whose scopes include one that can change data (for example gmail.modify) is refused with the new code write_scope_refused and nothing is stored; a grant that already holds such a scope refreshes with only its read-only scopes, and keeps working when Google narrows the token. If you see write_scope_refused, run gbrain google connect --reauth <email>. The OAuth client is now saved only together with a finished consent, so an abandoned or failed consent leaves the previous client and connection in place." },
  { since: '0.60.774.0', id: 'google_vault_lock_fail_closed_gst3849', kind: 'fix', text: "The credential vault lock no longer proceeds without the lock after 5 seconds or takes over a lock just because it is 10 seconds old. A writer that cannot take the lock now fails with vault_lock_busy (retry), and only a lock whose process is gone, or one older than a minute, is taken over. Each Google account's grant now carries a generation bumped by every consent, reconnect and import; a token refresh writes only onto the generation it read, so a refresh that races a disconnect or reconnect is dropped (vault_generation_changed) instead of writing the old grant back. Refreshes of one grant are serialized across processes." },
  { since: '0.60.774.0', id: 'google_personal_mode_gst3849', kind: 'add', text: "gbrain google setup --personal --account <email> connects an account through Google's one-click Personal mode: its own private Google app and OAuth client, stored with that account, with no weekly sign-out. gbrain google connect --import - takes a consented grant on stdin and validates it (account proof, read-only scopes) before writing. gbrain sources set-access <id> vault moves a Google source off the shared gbrain.io relay onto the account's own connection, keeping its id, private senders and ingest tiers. Once any account has its own client, credentials.json is written as version 2 and older gbrain binaries refuse to read it rather than overwrite it; upgrade every gbrain that shares the same GBRAIN_HOME." },
  { since: '0.60.774.0', id: 'google_status_refresh_health_gst3849', kind: 'fix', text: "gbrain google status now counts a failed refresh probe: the JSON ok field is false and the exit code is 1 while any account's refresh fails, where it used to report ok. With --no-probe each account reports refresh_probe: unprobed instead of omitting it, so unchecked is never read as healthy. status also takes --account <email> and reports each account's client_mode and grant_generation." },
  { since: '0.60.774.0', id: 'setup_history_import_offer', kind: 'add', text: "New: gbrain setup claude-code and gbrain setup codex now offer, on a brain the same setup run created, to import the coding-agent sessions already on the machine, so a new session can recall them on day one. Nothing is imported until someone says yes. At a terminal setup shows what it found and asks to import the newest session ([Y/n]), then the rest of the last 30 days on a second, explicit yes ([y/N]). Off a terminal or with --json the offer is the setup_history decision in the first-run bundle; its accept command is gbrain setup <harness> --history-decision <id>, used once. --history none skips for one run, --history decline stops the offer, and --history latest or --history <1-30> imports at once. The import writes one redacted page per conversation per day into the private conversations source with no model or provider call, never changes the archive switch, and is never offered on an upgraded, restored, shared, pinned or team brain. Afterwards setup prints what the brain holds, each count marked measured, off or unavailable, and three questions built from the imported sessions." },
  { since: '0.60.774.0', id: 'archive_stops_on_audience_change_setup', kind: 'fix', text: "The history import gbrain setup runs checks the brain's audience again before it publishes each day: when a member is added while it runs and the brain turns shared, it stops with archive_audience_changed before the next day is written, and the pages already written are kept to the owner. Rerun gbrain transcripts archive run once the member change is done. Ordinary gbrain transcripts archive run and backfill runs are unchanged: they still read the audience once, under the archive run lock." },
  { since: '0.60.774.0', id: 'setup_codex_waits_for_startup_gst3901', kind: 'fix', text: "`gbrain setup codex` now sets `mcp_optional_startup_grace_ms = 0` at the top of `$CODEX_HOME/config.toml`. Codex 0.147 and newer otherwise wait one second for an MCP server that is not marked required and then run the whole session without it, so a Codex session sometimes had no gbrain tools when gbrain started slowly. With the key at 0, Codex 0.151 and newer wait for each MCP server in that config up to its own `startup_timeout_sec` (10 seconds unless set) and start without a server that is broken. Codex 0.147 to 0.150 have no such setting and ignore the key, except that `codex exec --strict-config` refuses a config that has it. Setup writes the key only when it is not already set, keeps any value you set yourself, and `gbrain setup codex --remove` deletes it only while it is still 0. Re-run `gbrain setup codex` to add it to an existing install; the Codex plugin and `codex mcp add` paths do not write it." },
  { since: '0.60.774.0', id: 'precedence_allowed_claims_gst3827', kind: 'add', text: "Search, query, recall and get_page results now say where each page's authority comes from in a new precedence field: record, approved, curated, doc, chat or external. Lean search rows show it only when it is not curated. Pages of type rule, and type facts pages marked claims: allowed, read as approved unless an outside sender wrote them or an agent wrote them over MCP; chat sources (the conversation archive, meetings, Google) read as chat; a guest source reads as external; everything else reads as curated. Set a source's class with gbrain sources set-precedence <id> <class>, or remove it with --clear. The label is information only: it changes no ranking and no trust level. New: gbrain claims check \"<draft>\" (MCP tool check_claims) checks the numbers in a draft against your allowed-claims facts pages and says for each one whether a dated line supports it, a line says another number, or nothing covers it; a sentence with several numbers is supported only when every number is. New brains get me/facts and company/facts marked claims: allowed; on an existing brain, add claims: allowed to the front matter of a facts page you want checked. The query keyword-count line now names the date, language or symbol filters that the search listing it points to cannot apply." },
];

